// נוצר אוטומטית מ-practice-src/ ע"י tools/build-sims.js. לא לערוך כאן.
const PRACTICE_SETS = {"x0sc1":{"id":"x0sc1","tier":0,"type":"sc","qs":[{"q":"My grandmother cannot read small letters without her glasses, so she always ___ them in her bag.","o":["sells","breaks","carries","washes"],"a":2,"ex":"«carries» = נושאת, לוקחת איתה. סבתא צריכה את המשקפיים כדי לקרוא, ולכן היא תמיד לוקחת אותם בתיק. «breaks» (שוברת) לא הגיוני: מי שצריך משקפיים לא שובר אותם תמיד, ו-«sells» (מוכרת) לא קשור לצורך לקרוא.","w":[["carry","לשאת, לקחת איתך"],["glasses","משקפיים"]]},{"q":"Entrance to the museum was free on Friday, ___ there was a long line of visitors at the door.","o":["so","although","unless","but"],"a":0,"ex":"«so» = לכן. הכניסה הייתה חינם, ולכן הגיעו הרבה מבקרים ונוצר תור ארוך: סיבה ותוצאה. «although» (למרות ש) ו-«but» (אבל) דורשים ניגוד, ואין ניגוד בין כניסה חינם לתור ארוך.","w":[["so","לכן, אז"],["entrance","כניסה"],["line","תור; שורה"]]},{"q":"Dana ___ her keys at home, so she had to wait outside until her brother came back.","o":["found","left","made","opened"],"a":1,"ex":"«left» = השאירה (מ-leave). דנה השאירה את המפתחות בבית, ולכן חיכתה בחוץ. «found» (מצאה) הפוך: מי שמצא את המפתחות לא צריך לחכות בחוץ.","w":[["leave","להשאיר; לעזוב"],["until","עד ש..."]]},{"q":"The old bridge is not strong enough for trucks; ___, only cars and bicycles may cross it.","o":["however","for example","although","therefore"],"a":3,"ex":"«therefore» = לכן. הגשר לא חזק מספיק למשאיות, ולכן רק מכוניות ואופניים יכולים לעבור. «however» (עם זאת) דורש ניגוד, אבל החלק השני הוא תוצאה של הראשון.","w":[["therefore","לכן"],["cross","לחצות, לעבור"],["truck","משאית"]]}]},"x0sc2":{"id":"x0sc2","tier":0,"type":"sc","qs":[{"q":"The soup was too ___ to eat, so we waited a few minutes for it to cool down.","o":["sweet","hot","cold","thin"],"a":1,"ex":"«hot» = חם. חיכו שהמרק יתקרר («cool down»), ולכן הוא היה חם מדי. «cold» (קר) הוא ההפך: מרק קר לא צריך להתקרר.","w":[["hot","חם"],["cool down","להתקרר"]]},{"q":"___ it was raining hard, the players continued the game until the end.","o":["Because","Unless","Since","Although"],"a":3,"ex":"«Although» = למרות ש. ירד גשם חזק, ובכל זאת השחקנים המשיכו לשחק: זה ניגוד. «Because» (כי) ו-«Since» (מכיוון ש) לא הגיוניים, כי גשם הוא לא סיבה להמשיך במשחק.","w":[["although","למרות ש... (+משפט)"],["continue","להמשיך"]]},{"q":"The doctor told Moshe to ___ sugar and to eat more fruit and vegetables instead.","o":["avoid","add","buy","prefer"],"a":0,"ex":"«avoid» = להימנע מ. הרופא אמר לו להימנע מסוכר ולאכול פירות וירקות במקומו («instead»). «prefer» (להעדיף) סותר את «instead»: אי אפשר להעדיף סוכר ולאכול משהו אחר במקומו.","w":[["avoid","להימנע מ..."],["instead","במקום זאת"]]},{"q":"Noa never eats ice cream ___ milk makes her feel sick.","o":["unless","so","because","although"],"a":2,"ex":"«because» = כי. נועה לא אוכלת גלידה כי חלב גורם לה להרגיש רע: החלק השני הוא הסיבה. «so» (לכן) הופך את הכיוון, ו-«although» (למרות ש) דורש ניגוד שאין כאן.","w":[["because","כי, מפני ש..."],["sick","חולה, לא טוב (בבטן)"]]}]},"x0sc3":{"id":"x0sc3","tier":0,"type":"sc","qs":[{"q":"The airport was very ___ during the holiday, with long lines at every counter.","o":["empty","quiet","small","crowded"],"a":3,"ex":"«crowded» = צפוף, מלא אנשים. תורים ארוכים בכל דלפק מראים שהיו בשדה התעופה הרבה אנשים. «empty» (ריק) ו-«quiet» (שקט) הפוכים לתיאור הזה.","w":[["crowded","צפוף, הומה אדם"],["counter","דלפק"]]},{"q":"You will not be allowed into the concert ___ you show your ticket at the gate.","o":["because","unless","after","so that"],"a":1,"ex":"«unless» = אלא אם כן. לא תוכל להיכנס להופעה אלא אם תראה כרטיס. «because» (כי) לא הגיוני: הצגת כרטיס היא לא סיבה לא להכניס מישהו.","w":[["unless","אלא אם כן"],["allow","להרשות"]]},{"q":"The teacher asked us to ___ our answers carefully before we handed in the test.","o":["throw","hide","check","forget"],"a":2,"ex":"«check» = לבדוק. המורה ביקש לבדוק את התשובות בזהירות לפני ההגשה. «hide» (להסתיר) ו-«forget» (לשכוח) לא הגיוניים, כי המורה צריך לראות את התשובות.","w":[["check","לבדוק"],["carefully","בזהירות, בקפידה"],["hand in","להגיש"]]},{"q":"Tamar loves animals; ___, she volunteers at a dog shelter every weekend.","o":["in fact","however","instead","otherwise"],"a":0,"ex":"«in fact» = למעשה, ויותר מזה. החלק השני מחזק את הראשון: תמר כל כך אוהבת בעלי חיים שהיא אפילו מתנדבת במקלט לכלבים. «however» (עם זאת) דורש ניגוד, ואין ניגוד בין אהבת חיות להתנדבות עם כלבים. «instead» (במקום זאת) ו-«otherwise» (אחרת) לא מתאימים למשמעות.","w":[["in fact","למעשה, ויותר מזה"],["volunteer","להתנדב"],["shelter","מקלט"]]}]},"x0sc4":{"id":"x0sc4","tier":0,"type":"sc","qs":[{"q":"The movie was so ___ that half of the audience fell asleep before the end.","o":["boring","exciting","funny","short"],"a":0,"ex":"«boring» = משעמם. חצי מהקהל נרדם, וזה קורה כשסרט משעמם. «exciting» (מרגש) ו-«funny» (מצחיק) הם ההפך: בסרט כזה אנשים לא נרדמים.","w":[["boring","משעמם"],["audience","קהל"]]},{"q":"Uri studied hard for the test for two weeks; ___, he got the highest grade in the class.","o":["in contrast","instead","as a result","otherwise"],"a":2,"ex":"«as a result» = כתוצאה מכך. אורי למד קשה, ולכן קיבל את הציון הכי גבוה. «in contrast» (לעומת זאת) דורש ניגוד, ואין ניגוד בין למידה לציון גבוה.","w":[["as a result","כתוצאה מכך"],["grade","ציון"]]},{"q":"This shirt is too ___ for me; do you have it in a larger size?","o":["long","cheap","wide","small"],"a":3,"ex":"«small» = קטן. הוא מבקש מידה גדולה יותר, ולכן החולצה קטנה מדי. «wide» (רחב) הפוך: מי שהחולצה רחבה עליו לא יבקש מידה גדולה יותר.","w":[["size","מידה, גודל"],["larger","גדול יותר"]]},{"q":"___ the heavy traffic, we arrived at the wedding on time.","o":["Because of","Despite","Thanks to","Instead of"],"a":1,"ex":"«Despite» = למרות. היו פקקים כבדים, ובכל זאת הגענו בזמן: זה ניגוד. «Because of» (בגלל) ו-«Thanks to» (הודות ל) לא הגיוניים, כי פקקים לא עוזרים להגיע בזמן.","w":[["despite","למרות (+שם עצם)"],["traffic","תנועה, פקקים"],["on time","בזמן"]]}]},"x0sc5":{"id":"x0sc5","tier":0,"type":"sc","qs":[{"q":"The farmers were happy because the rain finally ___ after three dry months.","o":["stopped","froze","returned","disappeared"],"a":2,"ex":"«returned» = חזר. אחרי שלושה חודשים יבשים הגשם סוף סוף חזר, ולכן החקלאים שמחו. «stopped» (נפסק) ו-«disappeared» (נעלם) לא מתאימים, כי בחודשים היבשים כבר לא היה גשם.","w":[["return","לחזור"],["finally","סוף סוף"],["dry","יבש"]]},{"q":"Shira speaks three languages, ___ her younger brother speaks only Hebrew.","o":["because","whereas","so","therefore"],"a":1,"ex":"«whereas» = בעוד ש, ואילו. שירה מדברת שלוש שפות, ואילו אחיה רק עברית: השוואה בין שני אנשים. «because» (כי) ו-«so» (לכן) יוצרים קשר של סיבה, ואין קשר כזה בין השפות שלה לשפה של אחיה.","w":[["whereas","בעוד ש..., ואילו"],["language","שפה"]]},{"q":"Please walk ___ in the hallway, because many of the patients are sleeping.","o":["loudly","quickly","angrily","quietly"],"a":3,"ex":"«quietly» = בשקט. החולים ישנים, ולכן צריך ללכת בשקט במסדרון. «loudly» (ברעש) הוא ההפך, ו-«quickly» (מהר) לא קשור לכך שאנשים ישנים.","w":[["quietly","בשקט"],["hallway","מסדרון"],["patient","מטופל, חולה"]]},{"q":"The bus came twenty minutes late, ___ I missed the first lesson of the day.","o":["so","although","unless","but"],"a":0,"ex":"«so» = לכן. האוטובוס איחר, ולכן פספסתי את השיעור הראשון: סיבה ותוצאה. «but» (אבל) ו-«although» (למרות ש) דורשים ניגוד, אבל פספוס השיעור הוא תוצאה של האיחור.","w":[["so","לכן, אז"],["miss","לפספס; להתגעגע"]]}]},"x0sc6":{"id":"x0sc6","tier":0,"type":"sc","qs":[{"q":"Before you cross the street, you should always look in both ___.","o":["pockets","directions","colors","minutes"],"a":1,"ex":"«directions» = כיוונים. לפני שחוצים כביש מסתכלים לשני הכיוונים, ימינה ושמאלה. «pockets» (כיסים) ו-«minutes» (דקות) לא קשורים לחציית כביש.","w":[["direction","כיוון"],["cross","לחצות"]]},{"q":"Eitan was very ___ when he heard that he had won first prize in the competition.","o":["excited","bored","tired","angry"],"a":0,"ex":"«excited» = נרגש. מי ששומע שזכה בפרס ראשון מתרגש. «bored» (משועמם) ו-«angry» (כועס) לא מתאימים לחדשות טובות כאלה.","w":[["excited","נרגש"],["competition","תחרות"],["prize","פרס"]]},{"q":"Mira usually takes the bus to work; ___, today she walked because the weather was so nice.","o":["therefore","for example","in addition","however"],"a":3,"ex":"«however» = עם זאת, אולם. בדרך כלל מירה נוסעת באוטובוס, אבל היום הלכה ברגל: זה ניגוד להרגל שלה. «therefore» (לכן) לא הגיוני, כי ההרגל לנסוע באוטובוס הוא לא הסיבה ללכת ברגל.","w":[["however","עם זאת, אולם"],["usually","בדרך כלל"]]},{"q":"Prices at the market are ___ than in the supermarket, so many families do their shopping there.","o":["higher","bigger","lower","later"],"a":2,"ex":"«lower» = נמוכים יותר. משפחות רבות קונות בשוק כי המחירים שם נמוכים יותר. «higher» (גבוהים יותר) ו-«bigger» (גדולים יותר) הם ההפך: מחירים גבוהים לא מושכים קונים.","w":[["lower","נמוך יותר"],["price","מחיר"]]}]},"x0rs1":{"id":"x0rs1","tier":0,"type":"rs","qs":[{"q":"Because the summer was very dry, the farmers in the north had a smaller harvest than usual.","o":["The summer was very dry because the farmers in the north harvested less than they usually do.","The farmers in the north harvested less than usual, since there was very little rain that summer.","Although the summer was very dry, the farmers in the north had a bigger harvest than usual.","The farmers in the north had a smaller harvest than usual, because they planted the wrong seeds."],"a":1,"ex":"«Because» הפך ל-«since» (מכיוון ש), «very dry» הפך ל-«very little rain», ו-«a smaller harvest» ל-«harvested less». הקיץ היבש נשאר הסיבה. התשובה עם «the wrong seeds» מחליפה את הסיבה בסיבה שאין במקור, ו-«bigger harvest» הופך את התוצאה.","w":[["harvest","יבול, קציר"],["since","מכיוון ש..."],["usual","רגיל"]]},{"q":"Most of the students in the class preferred to take the test on Thursday rather than on Sunday.","o":["All of the students in the class wanted to take the test on Thursday and not on Sunday.","Most of the students in the class preferred to take the test on Sunday rather than on Thursday.","Most of the students in the class did not want to take the test at all, on any day.","The majority of the students in the class would rather have the test on Thursday than on Sunday."],"a":3,"ex":"«Most» הפך ל-«The majority» (הרוב), ו-«preferred ... rather than» הפך ל-«would rather ... than» (מעדיפים). התשובה עם «All» משנה «רוב» ל«כולם», והתשובה עם «on Sunday rather than on Thursday» מחליפה בין הימים.","w":[["majority","רוב"],["would rather","מעדיף ש..."],["prefer","להעדיף"]]},{"q":"The museum allows children under six to enter for free, but adults must buy a ticket.","o":["Adults must pay for a museum ticket, while children younger than six get in at no cost.","Children under six must buy a ticket to the museum, but adults can enter it for free.","Both adults and children under six have to buy a ticket before they enter the museum.","The museum lets children of all ages enter for free, but adults must still buy a ticket."],"a":0,"ex":"«buy a ticket» הפך ל-«pay for a museum ticket», «for free» הפך ל-«at no cost», ו-«under six» ל-«younger than six». התשובה הראשונה מחליפה בין המבוגרים לילדים, והתשובה עם «children of all ages» משנה את הכמות: לא רק ילדים מתחת לגיל שש.","w":[["allow","להרשות"],["at no cost","ללא עלות, בחינם"],["while","בעוד ש..."]]}]},"x0rs2":{"id":"x0rs2","tier":0,"type":"rs","qs":[{"q":"Dan rarely eats breakfast at home, because he usually wakes up late.","o":["Dan usually wakes up late because he rarely eats breakfast at home.","Dan often eats breakfast at home, even though he usually wakes up late.","Since Dan tends to get up late, he seldom has breakfast at home.","Dan rarely eats breakfast at home, because his family does not cook."],"a":2,"ex":"«rarely» = «seldom» (לעיתים רחוקות), ו-«usually wakes up late» = «tends to get up late». הקימה המאוחרת נשארה הסיבה. התשובה הראשונה הופכת סיבה ותוצאה, ו-«often» (לעיתים קרובות) הופך את «rarely».","w":[["rarely","לעיתים רחוקות"],["seldom","לעיתים רחוקות"],["tend to","נוטה ל..."]]},{"q":"The new phone is lighter than the old model, but its battery does not last as long.","o":["The new phone weighs less than the old model, but the old model's battery lasts longer.","The new phone is heavier than the old model, and its battery does not last as long.","The new phone is lighter than the old model, and its battery also lasts much longer.","The new phone is lighter than the old model because its battery is much smaller."],"a":0,"ex":"«lighter» = «weighs less» (שוקל פחות). «its battery does not last as long» אומר שהסוללה של הטלפון החדש מחזיקה פחות, כלומר הסוללה של הדגם הישן מחזיקה יותר. התשובה עם «heavier» הופכת את המשקל, והתשובה האחרונה מוסיפה סיבה שאין במקור.","w":[["light","קל (במשקל)"],["weigh","לשקול"],["last","להחזיק מעמד, להימשך"]]},{"q":"If it rains tomorrow, the school trip to the beach will be moved to next week.","o":["The school trip to the beach will take place tomorrow, even if it rains all day long.","In case of rain tomorrow, the class trip to the beach will take place next week instead.","If it rains tomorrow, the school trip to the beach will be cancelled and not happen at all.","Because it rained last week, the school trip to the beach was moved to tomorrow."],"a":1,"ex":"«If it rains» הפך ל-«In case of rain» (במקרה של גשם), ו-«will be moved to next week» ל-«will take place next week instead». התשובה עם «even if it rains» סותרת את התנאי, והתשובה עם «cancelled» אומרת שהטיול יבוטל ולא יידחה.","w":[["in case of","במקרה של"],["take place","להתקיים"],["instead","במקום זאת"]]}]},"x0rs3":{"id":"x0rs3","tier":0,"type":"rs","qs":[{"q":"Many tourists visit the old city in the spring, when the weather is neither too hot nor too cold.","o":["Few tourists visit the old city in the spring, because the weather is too cold for them.","Many tourists visit the old city in the summer, when the weather is very hot and dry.","Many tourists visit the old city in the spring, although the weather is often terrible.","The old city attracts many tourists in spring, as it is not too hot or too cold then."],"a":3,"ex":"«Many tourists visit» הפך ל-«attracts many tourists» (מושכת הרבה תיירים), ו-«neither too hot nor too cold» ל-«not too hot or too cold». התשובה עם «Few» הופכת את הכמות, והתשובה עם «terrible» אומרת שמזג האוויר גרוע, בניגוד למקור.","w":[["attract","למשוך"],["neither ... nor","לא ... וגם לא"]]},{"q":"The team lost the final game, even though its best player scored three goals.","o":["The team won the final game, because its best player scored three goals.","The team lost the final game, because its best player did not score any goals.","Despite three goals by its best player, the team did not win the final game.","The team's best player scored three goals in every game except the final."],"a":2,"ex":"«even though» (אף על פי ש) הפך ל-«Despite» (למרות), ו-«lost» הפך ל-«did not win». התשובה עם «won» הופכת את התוצאה, והתשובה עם «did not score any goals» סותרת את שלושת השערים.","w":[["even though","אף על פי ש..."],["despite","למרות (+שם עצם)"],["score","להבקיע"]]},{"q":"Only a few people came to the meeting, so the manager decided to hold it again next month.","o":["Many people came to the meeting, so the manager decided not to hold it again.","Only a few people came to the meeting, because the manager held it last month.","The manager has decided to hold the meeting again next month, since very few people attended it.","The manager decided to cancel all meetings next month, although many people came."],"a":2,"ex":"«decided» נשאר («has decided»), «so» (לכן) הפך ל-«since» (מכיוון ש) וסדר החלקים התהפך, ו-«came» הפך ל-«attended» (השתתפו). התשובה עם «Many people» הופכת את הכמות, והתשובה עם «because the manager held it last month» הופכת את הסיבה והתוצאה.","w":[["attend","להשתתף, להגיע ל..."],["hold a meeting","לקיים פגישה"],["a few","מעט, כמה"]]}]},"x0rs4":{"id":"x0rs4","tier":0,"type":"rs","qs":[{"q":"Unlike her sister, who loves the city, Michal prefers to live in a quiet village.","o":["Like her sister, Michal loves the city and does not want a quiet village.","Michal loves the city, but her sister prefers to live in a quiet village.","Michal and her sister both moved from the city to a quiet village.","Michal would rather live in a quiet village, whereas her sister loves city life."],"a":3,"ex":"«Unlike» (בניגוד ל) הפך ל-«whereas» (ואילו), ו-«prefers» ל-«would rather». התשובה עם «Like her sister» (כמו אחותה) הופכת את הניגוד לדמיון, והתשובה השנייה מחליפה בין מיכל לאחותה.","w":[["unlike","בניגוד ל... (+שם עצם)"],["whereas","בעוד ש..., ואילו"],["village","כפר"]]},{"q":"Doctors say that walking for thirty minutes a day can improve sleep.","o":["Doctors say that a thirty-minute walk every day always cures sleep problems.","According to doctors, a daily half-hour walk may help people sleep better.","Doctors say that people who sleep better tend to walk thirty minutes a day.","Doctors say that walking for thirty minutes at night can make sleep worse."],"a":1,"ex":"«thirty minutes» = «half-hour» (חצי שעה), «can improve» = «may help ... better» (יכול לשפר). התשובה עם «always cures» משנה «יכול לעזור» ל«תמיד מרפא», והתשובה עם «people who sleep better» הופכת סיבה ותוצאה.","w":[["improve","לשפר"],["according to","לפי"],["daily","יומי"]]},{"q":"The restaurant became popular soon after a famous chef started working in its kitchen.","o":["Not long after a well-known chef joined its kitchen, the restaurant became popular.","The famous chef started working in the restaurant because it was already popular.","The restaurant lost many customers soon after a famous chef started working there.","The restaurant became popular long before a famous chef started working there."],"a":0,"ex":"«soon after» = «Not long after» (זמן קצר אחרי), ו-«famous» = «well-known» (מפורסם). התשובה עם «long before» (הרבה לפני) משנה את סדר הזמנים, והתשובה עם «lost many customers» הופכת את התוצאה.","w":[["soon after","זמן קצר אחרי"],["well-known","ידוע, מפורסם"],["popular","פופולרי, אהוד"]]}]},"x0rs5":{"id":"x0rs5","tier":0,"type":"rs","qs":[{"q":"Children who read every day usually learn new words faster than children who do not.","o":["Children who read every day always learn every new word faster than other kids.","Children who do not read every day usually learn new words faster than those who do.","Children read every day because they want to learn new words faster than friends.","In general, kids who do not read daily learn new words more slowly than kids who do."],"a":3,"ex":"«usually» הפך ל-«In general» (באופן כללי), וההשוואה התהפכה: מי שלא קורא לומד «more slowly» (לאט יותר), וזו אותה משמעות. התשובה עם «always ... every new word» משנה «בדרך כלל» ל«תמיד», והתשובה השנייה הופכת את ההשוואה.","w":[["in general","באופן כללי"],["slowly","לאט"],["daily","יומי, כל יום"]]},{"q":"The shop will give you your money back if you return the shoes within two weeks.","o":["If you bring the shoes back no later than two weeks after buying them, you will get a refund.","The shop will give your money back only if you keep the shoes for more than two weeks.","The shop never gives money back, even if you return the shoes within two weeks of buying them.","If you return the shoes within two weeks, the shop will give you a new pair for free."],"a":0,"ex":"«return» = «bring back» (להחזיר), «within two weeks» = «no later than two weeks» (לא יאוחר משבועיים), ו-«give you your money back» = «refund» (החזר כספי). התשובה עם «never» סותרת את המקור, והתשובה עם «a new pair» מחליפה את החזר הכסף בזוג חדש.","w":[["refund","החזר כספי"],["within","בתוך, תוך"],["no later than","לא יאוחר מ..."]]},{"q":"Although the hotel was far from the beach, the guests enjoyed their stay there.","o":["The guests did not enjoy their stay, because the hotel was far from the beach.","The guests enjoyed their stay because the hotel was right next to the beach.","The guests had a good time at the hotel, even though it was not close to the beach.","The hotel was far from the beach, so the guests spent their stay at the pool."],"a":2,"ex":"«Although» הפך ל-«even though», «enjoyed» ל-«had a good time», ו-«far from» ל-«not close to». התשובה הראשונה הופכת את ההנאה, והתשובה עם «right next to the beach» סותרת את המרחק מהחוף.","w":[["even though","אף על פי ש..."],["stay","שהייה"],["far from","רחוק מ..."]]}]},"x0rs6":{"id":"x0rs6","tier":0,"type":"rs","qs":[{"q":"The price of the concert tickets was reduced, and as a result, many more people bought them.","o":["Many more people bought concert tickets, so the price of the tickets went up.","Because the concert tickets became cheaper, a lot more people decided to buy them.","The concert tickets became cheaper, but fewer people decided to buy them this time.","The price of the concert tickets went down because many people complained about it."],"a":1,"ex":"«was reduced» (הורד) = «became cheaper» (הפך לזול יותר), ו-«as a result» הפך ל-«Because» בתחילת המשפט, באותו כיוון: המחיר ירד ולכן קנו יותר. התשובה עם «fewer people» הופכת את התוצאה, והתשובה עם «complained» מוסיפה סיבה שאין במקור.","w":[["reduce","להפחית, להוריד"],["as a result","כתוצאה מכך"],["complain","להתלונן"]]},{"q":"Ron had never seen snow before he moved to Canada at the age of twenty.","o":["Ron had seen snow many times before he moved to Canada at age twenty.","Until he moved to Canada at twenty, Ron had not seen snow even once.","Ron moved to Canada at the age of twenty because he wanted to see snow.","Ron moved to Canada at the age of twenty, after seeing snow there on a trip."],"a":1,"ex":"«never ... before he moved» הפך ל-«Until he moved ... had not seen snow even once» (עד שעבר, לא ראה שלג אפילו פעם אחת). התשובה עם «many times» סותרת את «never», התשובה עם «after seeing snow there on a trip» אומרת שראה שלג לפני המעבר, והתשובה עם «because he wanted to see snow» מוסיפה סיבה שאין במקור.","w":[["never","אף פעם"],["until","עד ש..."],["even once","אפילו פעם אחת"]]},{"q":"Not all of the plants in the garden need much water; some can live for weeks without it.","o":["All of the plants in the garden need a lot of water and die quickly without it.","None of the plants in the garden can live for more than a few days without water.","Some plants in the garden do not need much water and can survive for weeks without any.","All of the plants in the garden can live for weeks without water, so none need much."],"a":2,"ex":"«Not all ... need much water» (לא כולם צריכים הרבה מים) אומר שיש צמחים שלא צריכים, וזה «Some plants ... do not need much water». «live» הפך ל-«survive» (לשרוד). התשובות עם «All» ו-«None» משנות את הכמות: המקור מדבר רק על חלק מהצמחים.","w":[["not all","לא כל ה..."],["survive","לשרוד"],["none","אף אחד, אף לא אחד"]]}]},"x0rc1":{"id":"x0rc1","tier":0,"type":"rc","title":"Why Onions Make Us Cry","text":["Many people who cook have had the same experience: they start cutting an onion, and a few seconds later tears are running down their face. The onion is not making them sad, of course. Instead, it is defending itself, and the cook's eyes are simply caught in the middle.","An onion growing in the ground has a problem: it cannot run away from animals that want to eat it. For this reason, it has a chemical defense. As long as the onion is whole, certain substances inside its cells are kept apart. When a knife breaks the cells, these substances mix and quickly produce a gas. The gas does not harm the onion, but it is an unpleasant surprise for an animal that bites into it.","When the gas reaches our eyes, it irritates the small nerves on their surface, and these nerves send a message to the brain. The brain answers by telling the eyes to make more tears, in order to wash the gas away. In other words, the tears are not a sign of damage. They are the body's way of protecting itself.","Cooks have found several ways to cry less. Putting the onion in the refrigerator for half an hour helps, because the chemical reactions are slower when the onion is cold. A sharp knife is also useful, since it breaks fewer cells than a dull one. Some people even cut onions next to an open window or a fan, so that the gas blows away before it reaches their eyes."],"qs":[{"q":"The passage mainly explains","o":["why cutting onions makes people cry","how to grow onions without chemicals","why tears show that the eyes are damaged","which kitchen tools are best for cooking"],"a":0,"ex":"כל הקטע מסביר למה חיתוך בצל גורם לדמעות: ההגנה הכימית של הבצל (פסקה 2), מה קורה בעין (פסקה 3) ואיך לבכות פחות (פסקה 4). האפשרות על דמעות כסימן לנזק סותרת את פסקה 3, שאומרת שהדמעות «are not a sign of damage».","w":[["mainly","בעיקר"],["explain","להסביר"]]},{"q":"According to the second paragraph, the gas is produced when","o":["the onion is kept in a cold place","the onion grows too large in the ground","water touches the outside of the onion","the cells of the onion are broken"],"a":3,"ex":"בפסקה 2 כתוב «When a knife breaks the cells, these substances mix and quickly produce a gas»: הגז נוצר כשהתאים נשברים. מקום קר מוזכר רק בפסקה 4, ושם הוא מאט את התגובה ולא יוצר את הגז.","w":[["produce","לייצר"],["cell","תא"],["substance","חומר"]]},{"q":"In the third paragraph, the word 'They' in 'They are the body's way of protecting itself' refers to","o":["the eyes","the tears","the nerves","the cells"],"a":1,"ex":"המשפט שלפני אומר «the tears are not a sign of damage», והמשפט הבא ממשיך «They are the body's way of protecting itself»: הדמעות הן הדרך של הגוף להגן על עצמו, כי הן שוטפות את הגז מהעין. העצבים (nerves) רק מרגישים את הגז ושולחים הודעה למוח.","w":[["refer to","להתייחס ל..."],["protect","להגן"],["nerve","עצב"]]},{"q":"It can be inferred from the last paragraph that cutting a warm onion with a dull knife would probably","o":["produce less gas than usual","make the onion taste better","cause more tears than usual","stop the chemical reactions"],"a":2,"ex":"בפסקה 4 כתוב שבצל קר התגובות איטיות יותר, ושסכין חדה שוברת פחות תאים מסכין קהה («dull»). לכן בצל חם וסכין קהה יעשו את ההפך: יותר גז ויותר דמעות. «produce less gas» הפוך למה שאפשר להסיק.","w":[["infer","להסיק"],["dull","קהה"],["sharp","חד"]]},{"q":"Why does the writer mention animals in the second paragraph?","o":["to show that animals also cry when they eat onions","to explain why onions have a chemical defense","to suggest that onions are dangerous for pets","to compare onions with other vegetables"],"a":1,"ex":"בפסקה 2 כתוב שהבצל לא יכול לברוח מבעלי חיים שרוצים לאכול אותו, «For this reason, it has a chemical defense». בעלי החיים מוזכרים כדי להסביר למה יש לבצל הגנה. הקטע לא אומר שבעלי חיים בוכים או שבצל מסוכן לחיות מחמד.","w":[["mention","להזכיר"],["defense","הגנה"]]}]},"x0rc2":{"id":"x0rc2","tier":0,"type":"rc","title":"Built for the Desert","text":["Few animals are as well suited to the desert as the camel. For thousands of years, people in North Africa and the Middle East have used camels to carry goods across hot, dry lands where horses would quickly die. Their ability to go for a long time without drinking has made them famous, but it has also led to some popular mistakes.","The most common mistake is the belief that a camel stores water in its hump. In fact, the hump is made mostly of fat. When food is hard to find, the camel's body uses this fat for energy, and the hump becomes smaller and may even fall to one side. Keeping the fat in one place, instead of all over the body, also helps the camel lose heat more easily.","The real secret is the way a camel uses water. It loses very little water through sweat, because its body temperature can rise by several degrees during the day before it starts to sweat. It can also lose about a quarter of its body weight in water and still survive, something that would kill most other mammals. When it finally reaches water, a thirsty camel can drink more than 100 liters in about ten minutes.","Other parts of the camel's body help as well. Two rows of long eyelashes protect its eyes from blowing sand, and it can close its nostrils during a sandstorm. Its wide feet spread its weight, so it does not sink into soft sand. Thanks to all these features, the camel can travel where few other large animals can."],"qs":[{"q":"Which of the following is the best title for the passage?","o":["How Horses Cross the Desert","Why Camels Are Disappearing","The History of Desert Trade","The Camel: Made for Desert Life"],"a":3,"ex":"כל הקטע מתאר איך הגוף של הגמל מותאם למדבר: הדבשת, השימוש במים, הריסים והרגליים. סוסים מוזכרים רק במשפט אחד, ובקטע אין שום דבר על כך שגמלים נעלמים.","w":[["suited to","מתאים ל..."],["title","כותרת"]]},{"q":"According to the second paragraph, a camel's hump","o":["is full of water that the camel drinks later","grows larger when food is hard to find","contains mostly fat that the camel uses for energy","makes it harder for the camel to lose heat"],"a":2,"ex":"בפסקה 2 כתוב «the hump is made mostly of fat», והגוף משתמש בשומן הזה לאנרגיה. המים בדבשת הם בדיוק «the most common mistake», והדבשת קטנה, לא גדלה, כשאין אוכל.","w":[["hump","דבשת"],["store","לאחסן"],["fat","שומן"]]},{"q":"In the third paragraph, the phrase 'the real secret' refers to","o":["the way the camel uses water","the fat stored in the hump","the camel's long eyelashes","the camel's wide feet"],"a":0,"ex":"המשפט אומר «The real secret is the way a camel uses water». אחרי שפסקה 2 הסבירה שהדבשת לא שומרת מים, פסקה 3 מסבירה מה באמת מאפשר לגמל לחיות בלי לשתות. הריסים והרגליים מופיעים רק בפסקה 4.","w":[["secret","סוד"],["sweat","זיעה; להזיע"]]},{"q":"Which of the following is NOT mentioned in the passage as something that helps the camel in the desert?","o":["thick fur that keeps out the sun","closing its nostrils in a sandstorm","wide feet that do not sink into sand","long eyelashes that protect its eyes"],"a":0,"ex":"פרווה עבה לא מוזכרת בשום מקום בקטע. שלוש האפשרויות האחרות מופיעות בפסקה 4: הריסים הארוכים, סגירת הנחיריים בסופת חול והרגליים הרחבות.","w":[["mention","להזכיר"],["nostril","נחיר"],["eyelash","ריס"]]},{"q":"The writer mentions horses in the first paragraph in order to","o":["explain that horses are faster than camels","suggest that horses can carry more goods","show that camels can survive where other animals cannot","describe how horses store water in the desert"],"a":2,"ex":"בפסקה 1 כתוב שגמלים נושאים סחורה באזורים «where horses would quickly die». הסוסים מוזכרים כדי להראות שהגמל שורד במקום שבו בעלי חיים אחרים לא שורדים. הקטע לא משווה מהירות או כמות סחורה.","w":[["in order to","כדי ל..."],["goods","סחורה"]]}]},"x0rc3":{"id":"x0rc3","tier":0,"type":"rc","title":"The Power of 99","text":["Walk into almost any shop and you will see prices like 9.99 or 49.90 instead of 10 or 50. The difference is only a few cents, so why do sellers bother? The answer has less to do with money than with the way our brains read numbers.","When we read a price, we start from the left, and we pay the most attention to the first digit. By the time we reach the end, we have often already formed an opinion. As a result, 2.99 feels closer to 2 than to 3, even though it is almost exactly 3. Researchers call this the 'left-digit effect.' In several studies, shoppers bought more of a product when its price ended in 9, even when the difference was just one cent.","Prices ending in 9 also send a message. Many shoppers have learned to connect them with sales and special offers. For this reason, a price of 39 may seem like a bargain, while 40 seems like a normal price, although the store earns almost the same amount of money in both cases.","Interestingly, expensive shops often do the opposite. A fancy restaurant or a jewelry store may choose round prices such as 100 or 500. Round numbers feel simple and confident, and they suggest quality rather than a discount. In other words, the right price depends not only on how much a product costs, but also on what the seller wants customers to feel."],"qs":[{"q":"The passage mainly discusses","o":["how shops decide which products to sell","how much money shops lose during sales","why expensive shops are more successful","why sellers often use prices that end in 9"],"a":3,"ex":"הקטע פותח בשאלה למה מוכרים משתמשים במחירים כמו 9.99, ועונה עליה: איך המוח קורא מספרים (פסקה 2) והמסר של מבצע (פסקה 3). גם פסקה 4 עוסקת באותו נושא, כי היא מסבירה מתי בוחרים דווקא במחיר עגול.","w":[["discuss","לדון ב..."],["seller","מוכר"]]},{"q":"According to the second paragraph, when people read a price, they","o":["look at the last digit before the others","pay the most attention to the first digit","always round it up to the next number","compare it with prices in other shops"],"a":1,"ex":"בפסקה 2 כתוב «we pay the most attention to the first digit». האפשרות על הספרה האחרונה הפוכה, כי קוראים משמאל, וקונים לא מעגלים למעלה: לכן 2.99 מרגיש קרוב ל-2.","w":[["digit","ספרה"],["attention","תשומת לב"],["round up","לעגל כלפי מעלה"]]},{"q":"In the third paragraph, the word 'bargain' probably means","o":["a product of very high quality","a price that is hard to read","a normal, everyday purchase","something sold at a good, low price"],"a":3,"ex":"בפסקה 3 מחירים שנגמרים ב-9 מזכירים «sales and special offers» (מבצעים), והמחיר 39 נראה «bargain» לעומת 40 שנראה «a normal price». לכן «bargain» = מציאה, משהו זול. «a normal, everyday purchase» הוא בדיוק מה שהמשפט מנגיד ל-bargain.","w":[["bargain","מציאה"],["special offer","מבצע"]]},{"q":"The main purpose of the last paragraph is to","o":["explain why some shops prefer round prices","show that round prices make products cheaper","describe the history of the jewelry business","warn customers about fancy restaurants"],"a":0,"ex":"הפסקה האחרונה מסבירה שחנויות יקרות בוחרות במחירים עגולים, כי הם מרמזים על איכות ולא על הנחה. היא לא אומרת שמחירים עגולים מוזילים מוצרים, ולא מספרת היסטוריה.","w":[["purpose","מטרה"],["round","עגול"],["quality","איכות"]]},{"q":"It can be inferred from the passage that a shop that wants its customers to think a product is on sale would probably choose the price","o":["80.00","100.00","79.99","200.00"],"a":2,"ex":"לפי פסקאות 2 ו-3 מחיר שנגמר ב-9 נראה זול יותר ומזכיר מבצע, ולכן 79.99 מתאים. המחירים העגולים 80.00, 100.00 ו-200.00 נראים לפי פסקה 4 כמו מחיר רגיל או סימן לאיכות, לא כמו הנחה.","w":[["on sale","במבצע"],["infer","להסיק"]]}]},"x1sc1":{"id":"x1sc1","tier":1,"type":"sc","qs":[{"q":"The new drug looked promising in the laboratory, but it had to be ___ after several patients suffered serious side effects.","o":["endorsed","enhanced","withdrawn","imitated"],"a":2,"ex":"«withdrawn» = נמשך, הוסר (מהשוק). המילה «but» מראה ניגוד: התרופה נראתה מבטיחה במעבדה, אבל אחרי תופעות לוואי קשות היה צריך להסיר אותה. «endorsed» (קיבל תמיכה, אושר) ו-«enhanced» (שופר) הם תוצאות חיוביות שלא מתאימות לתופעות לוואי קשות.","w":[["withdraw","למשוך, להסיר"],["promising","מבטיח, מעורר תקווה"],["side effect","תופעת לוואי"]]},{"q":"The ancient road was built more than two thousand years ago; ___, parts of it are still used by local farmers today.","o":["even so","therefore","in other words","similarly"],"a":0,"ex":"«even so» = ובכל זאת, למרות זאת. הדרך נבנתה לפני יותר מאלפיים שנה, ולמרות הגיל הרב חלקים ממנה עדיין בשימוש, וזה ניגוד. «therefore» (לכן) היה הופך את הגיל לסיבה לשימוש, ו-«in other words» (במילים אחרות) מציג ניסוח מחדש של אותו רעיון, וזה לא המצב כאן.","w":[["even so","ובכל זאת, למרות זאת"],["in other words","במילים אחרות"],["similarly","באופן דומה"]]},{"q":"The village is so ___ that the nearest hospital is a three-hour drive away over narrow mountain roads.","o":["crowded","modern","fertile","remote"],"a":3,"ex":"«remote» = מרוחק, נידח. בית החולים הקרוב נמצא במרחק שלוש שעות נסיעה בדרכי הרים, כלומר הכפר רחוק מכל מקום. «crowded» (צפוף) ו-«modern» (מודרני) לא מסבירים את המרחק הגדול מבית החולים.","w":[["remote","מרוחק, נידח"],["crowded","צפוף"],["fertile","פורה (אדמה)"]]},{"q":"___ he had no formal training in music, the composer wrote several works that are still performed today.","o":["Because","Even though","As long as","So that"],"a":1,"ex":"«Even though» = אף על פי ש. אין לו הכשרה פורמלית במוזיקה, ובכל זאת הוא כתב יצירות שמבוצעות עד היום, וזה ניגוד. «Because» (מפני ש) היה הופך את חוסר ההכשרה לסיבה להצלחה, ו-«As long as» (כל עוד) הוא תנאי שלא מתאים לעובדה שכבר קרתה.","w":[["even though","אף על פי ש... (+משפט)"],["formal training","הכשרה פורמלית"],["perform","לבצע (יצירה), להופיע"]]}]},"x1sc2":{"id":"x1sc2","tier":1,"type":"sc","qs":[{"q":"The two witnesses gave ___ accounts of the accident: one said the car was red, while the other insisted it was blue.","o":["identical","conflicting","detailed","accurate"],"a":1,"ex":"«conflicting» = סותרים. אחרי הנקודתיים מוסבר שעד אחד אמר שהמכונית אדומה והשני התעקש שהיא כחולה, כלומר העדויות סותרות זו את זו. «identical» (זהים) הפוך לגמרי, ו-«accurate» (מדויקים) לא ייתכן כששני העדים אומרים דברים שונים.","w":[["conflicting","סותר, מנוגד"],["witness","עד (ראייה)"],["insist","להתעקש, לעמוד על כך"]]},{"q":"Sea otters eat large numbers of sea urchins, ___ protecting the kelp forests that the urchins feed on.","o":["whereas","unless","instead","thereby"],"a":3,"ex":"«thereby» = ובכך, על ידי כך. הלוטרות אוכלות קיפודי ים, וכך הן מגינות על יערות האצות שהקיפודים ניזונים מהם: הפעולה הראשונה מובילה לתוצאה. «whereas» (ואילו) מציג ניגוד בין שני נושאים, ו-«unless» (אלא אם כן) הוא תנאי, ושניהם לא מתאימים לצורה protecting שבאה אחריהם.","w":[["thereby","ובכך, על ידי כך"],["whereas","ואילו, בעוד ש..."],["feed on","להיזון מ..."]]},{"q":"The manager asked the team to ___ the report to two pages, since the board members had very little time to read it.","o":["condense","expand","translate","publish"],"a":0,"ex":"«condense» = לתמצת, לקצר. המנהל רוצה דוח של שני עמודים כי לחברי ההנהלה אין זמן לקרוא, כלומר צריך לקצר אותו. «expand» (להרחיב) הפוך, ו-«translate the report to two pages» (לתרגם לשני עמודים) לא הגיוני.","w":[["condense","לתמצת, לקצר"],["expand","להרחיב"],["board","הנהלה, דירקטוריון"]]},{"q":"Wolves usually hunt in packs, ___ foxes tend to hunt alone.","o":["because","so that","whereas","provided that"],"a":2,"ex":"«whereas» = ואילו, בעוד ש. המשפט משווה בין שני בעלי חיים: זאבים צדים בלהקה, ושועלים צדים לבד. «because» (מפני ש) היה הופך את השועלים לסיבה להתנהגות של הזאבים, ו-«provided that» (בתנאי ש) יוצר תנאי לא הגיוני.","w":[["whereas","ואילו, בעוד ש..."],["pack","להקה"],["tend to","נוטה ל..."]]}]},"x1sc3":{"id":"x1sc3","tier":1,"type":"sc","qs":[{"q":"The museum's collection was severely damaged in the flood, and it will take years to ___ the most valuable paintings.","o":["restore","abandon","purchase","display"],"a":0,"ex":"«restore» = לשקם, לשחזר. הציורים נפגעו קשה בשיטפון, ולכן ייקח שנים להחזיר אותם למצבם הקודם. «display» (להציג) לא דורש שנים של עבודה, ו-«purchase» (לקנות) לא הגיוני כי הציורים כבר שייכים למוזיאון.","w":[["restore","לשקם, לשחזר"],["severely","באופן חמור, קשות"],["abandon","לנטוש"]]},{"q":"The company promised to lower its prices; ___, customers are still paying the same amount a year later.","o":["consequently","for example","however","in addition"],"a":2,"ex":"«however» = אולם, עם זאת. החברה הבטיחה להוריד מחירים, אבל אחרי שנה הלקוחות משלמים אותו דבר: ההבטחה לא קוימה, וזה ניגוד. «consequently» (כתוצאה מכך) היה הופך את ההבטחה לסיבה לכך שהמחיר לא ירד, ו-«in addition» (בנוסף) מוסיף רעיון באותו כיוון.","w":[["however","אולם, עם זאת"],["consequently","כתוצאה מכך"],["lower","להוריד, להפחית"]]},{"q":"Her ___ about the project disappeared once she saw how well the first tests had gone.","o":["enthusiasm","skepticism","ambition","gratitude"],"a":1,"ex":"«skepticism» = ספקנות. מה שנעלם אחרי שהבדיקות הראשונות הצליחו הוא משהו שלילי, כלומר הספקות שלה לגבי הפרויקט. «enthusiasm» (התלהבות) לא נעלמת בגלל הצלחה אלא דווקא גדלה, ו-«gratitude» (הכרת תודה) לא קשורה לתוצאות הבדיקות.","w":[["skepticism","ספקנות"],["enthusiasm","התלהבות"],["gratitude","הכרת תודה"]]},{"q":"Many fish species can survive only within a narrow range of temperatures, ___ even a small rise in water temperature may force them to move to cooler areas.","o":["unless","although","while","so"],"a":3,"ex":"«so» = ולכן. הדגים שורדים רק בטווח טמפרטורות צר, ולכן גם עלייה קטנה עלולה לאלץ אותם לעבור: סיבה ותוצאה. «although» (למרות ש) ו-«while» (בעוד ש) מציגים ניגוד שאין כאן, ו-«unless» (אלא אם כן) יוצר תנאי לא הגיוני.","w":[["range","טווח"],["force","לאלץ, להכריח"],["survive","לשרוד"]]}]},"x1sc4":{"id":"x1sc4","tier":1,"type":"sc","qs":[{"q":"The letters were written in a secret code, and historians needed nearly a decade to ___ them.","o":["forge","fold","ignore","decipher"],"a":3,"ex":"«decipher» = לפענח. מכתבים שנכתבו בקוד סודי צריך לפענח, וזו העבודה שלקחה להיסטוריונים כמעט עשור. «forge» (לזייף) ו-«ignore» (להתעלם) לא מתאימים לעבודה ארוכה של היסטוריונים על קוד.","w":[["decipher","לפענח"],["forge","לזייף"],["decade","עשור"]]},{"q":"___ repairing the old printer, the office decided to replace it with a new model.","o":["Because of","Instead of","In addition to","According to"],"a":1,"ex":"«Instead of» = במקום. המשרד בחר להחליף את המדפסת בחדשה, כלומר לא לתקן אותה. «In addition to» (בנוסף ל) לא הגיוני, כי אין טעם לתקן מדפסת שממילא מחליפים, ו-«Because of» (בגלל) היה הופך את התיקון לסיבה להחלפה.","w":[["instead of","במקום (+שם עצם / ing)"],["replace","להחליף"],["repair","לתקן"]]},{"q":"The plan looked good on paper, but it proved ___ in practice, since it required far more money than the town had.","o":["profitable","flexible","impractical","popular"],"a":2,"ex":"«impractical» = לא מעשי. «but» מראה ניגוד לכך שהתוכנית נראתה טוב על הנייר, והסיבה מופיעה בסוף: היא דרשה הרבה יותר כסף ממה שהיה לעיר. «profitable» (רווחי) ו-«popular» (פופולרי) הם חיוביים ולא מתאימים לניגוד ולסיבה.","w":[["impractical","לא מעשי"],["in practice","בפועל, במציאות"],["require","לדרוש"]]},{"q":"The author rarely gives interviews; ___, she spends most of the year alone on a small farm far from the city.","o":["in fact","nonetheless","otherwise","by contrast"],"a":0,"ex":"«in fact» = למעשה, יתרה מזו. החלק השני מחזק את הראשון: היא לא רק נמנעת מראיונות, אלא חיה רוב השנה לבד בחווה רחוקה. «nonetheless» (למרות זאת) ו-«by contrast» (לעומת זאת) מציגים ניגוד, אבל שני החלקים כאן מצביעים לאותו כיוון.","w":[["in fact","למעשה, בעצם"],["nonetheless","למרות זאת"],["by contrast","לעומת זאת"]]}]},"x1sc5":{"id":"x1sc5","tier":1,"type":"sc","qs":[{"q":"The new law ___ smoking in all restaurants and bars, so owners who allow it may now be fined.","o":["encourages","permits","prohibits","mentions"],"a":2,"ex":"«prohibits» = אוסר. בעלים שמרשים לעשן עלולים לקבל קנס, ולכן החוק אוסר עישון. «permits» (מתיר) ו-«encourages» (מעודד) הפוכים, כי אז לא היה סיבה לקנס.","w":[["prohibit","לאסור"],["fine","לקנוס; קנס"],["permit","להתיר, להרשות"]]},{"q":"The experiment was repeated three times ___ make sure that the results had not been caused by chance.","o":["as long as","instead of","rather than","in order to"],"a":3,"ex":"«in order to» = כדי ל. החזרה על הניסוי היא האמצעי, והמטרה היא לוודא שהתוצאות לא נבעו ממקרה. «instead of» ו-«rather than» (במקום) היו אומרים שהחוקרים לא רצו לוודא את התוצאות, וזה לא הגיוני, ו-«as long as» (כל עוד) צריך אחריו משפט שלם.","w":[["in order to","כדי ל... (+פועל)"],["make sure","לוודא"],["by chance","במקרה"]]},{"q":"The difference between the two paintings is so ___ that only an expert can tell which one is the original.","o":["subtle","obvious","dramatic","colorful"],"a":0,"ex":"«subtle» = עדין, דק, קשה להבחנה. רק מומחה יכול להבחין בין שני הציורים, כלומר ההבדל קטן מאוד. «obvious» (ברור, בולט) ו-«dramatic» (דרמטי) הפוכים, כי אז כל אחד היה רואה את ההבדל.","w":[["subtle","עדין, דק, קשה להבחנה"],["obvious","ברור, בולט"],["tell (the difference)","להבחין, לזהות"]]},{"q":"Sales of the phone fell sharply in its second year, ___ the company's decision to raise its price.","o":["in spite of","due to","regardless of","apart from"],"a":1,"ex":"«due to» = בשל, עקב. העלאת המחיר היא הסיבה לירידה החדה במכירות. «in spite of» (למרות) לא הגיוני, כי העלאת מחיר דווקא מסבירה ירידה במכירות, ו-«regardless of» (בלי קשר ל) מנתק את הקשר בין שני הדברים.","w":[["due to","בשל, עקב"],["sharply","באופן חד"],["regardless of","בלי קשר ל..."]]}]},"x1sc6":{"id":"x1sc6","tier":1,"type":"sc","qs":[{"q":"The professor's lectures were so ___ that students often left the hall more confused than when they had arrived.","o":["inspiring","incoherent","concise","entertaining"],"a":1,"ex":"«incoherent» = לא קוהרנטי, חסר רצף הגיוני. הסטודנטים יצאו מההרצאות מבולבלים יותר משנכנסו, ולכן ההרצאות היו לא ברורות. «inspiring» (מעורר השראה) ו-«concise» (תמציתי) הם תכונות חיוביות שלא היו מבלבלות את הסטודנטים.","w":[["incoherent","לא קוהרנטי, מבולבל"],["concise","תמציתי"],["confused","מבולבל"]]},{"q":"Some scientists believe the drought was caused by climate change; others, ___, argue that it was part of a natural cycle.","o":["on the other hand","as a result","for instance","in addition"],"a":0,"ex":"«on the other hand» = מצד שני. יש כאן שתי עמדות מנוגדות: חלק מהמדענים מאשימים את שינוי האקלים, ואחרים חושבים שזה מחזור טבעי. «as a result» (כתוצאה מכך) לא מתאים, כי העמדה השנייה לא נובעת מהראשונה, ו-«for instance» (לדוגמה) מציג דוגמה ולא עמדה מנוגדת.","w":[["on the other hand","מצד שני"],["drought","בצורת"],["cycle","מחזור"]]},{"q":"The company ___ its success to a small team of engineers who designed its first product in a garage.","o":["denies","prevents","exposes","attributes"],"a":3,"ex":"«attributes ... to» = מייחס ל. החברה אומרת שההצלחה שלה נובעת מצוות קטן של מהנדסים. «denies» (מכחישה) לא מתאים למבנה «to a small team», ו-«prevents» (מונעת) לא הגיוני, כי חברה לא מונעת את ההצלחה של עצמה.","w":[["attribute to","לייחס ל..."],["deny","להכחיש"],["expose","לחשוף"]]},{"q":"You may borrow up to five books at a time, ___ you return them within three weeks.","o":["even though","so that","as long as","whereas"],"a":2,"ex":"«as long as» = כל עוד, בתנאי ש. מותר לשאול עד חמישה ספרים בתנאי שמחזירים אותם תוך שלושה שבועות. «even though» (אף על פי ש) מציג ניגוד שאין כאן, ו-«so that» (כדי ש) היה אומר שמטרת ההשאלה היא להחזיר את הספרים.","w":[["as long as","כל עוד, בתנאי ש..."],["borrow","לשאול (חפץ)"],["at a time","בכל פעם"]]}]},"x1rs1":{"id":"x1rs1","tier":1,"type":"rs","qs":[{"q":"Although the new vaccine is highly effective, it must be stored at very low temperatures, which makes it difficult to distribute in rural areas.","o":["Because the new vaccine is stored at very low temperatures, it is less effective in rural areas than it is in cities.","The new vaccine works very well, but since it must be kept extremely cold, getting it to rural areas is hard.","The new vaccine is easy to distribute in rural areas, since it can be kept at normal temperatures without losing its effect.","People in rural areas have rejected the new vaccine because they doubt that it remains effective at low temperatures."],"a":1,"ex":"במקור: החיסון יעיל מאוד, אבל צריך לשמור אותו בטמפרטורה נמוכה מאוד, ולכן קשה להפיץ אותו באזורים כפריים. התשובה הנכונה אומרת את זה במילים אחרות («kept extremely cold», «getting it to rural areas is hard»). התשובה עם «less effective» משנה את הבעיה מהפצה ליעילות, התשובה עם «easy to distribute» הופכת את המשמעות, והתשובה עם «rejected» מוסיפה טענה שאין במקור.","w":[["effective","יעיל"],["store","לאחסן, לשמור"],["distribute","להפיץ, לחלק"]]},{"q":"The museum's attendance doubled after it began offering free entry on weekends, but its income from the gift shop barely changed.","o":["The museum began offering free weekend entry because its gift shop income had doubled, while attendance stayed about the same.","After weekend entry became free, attendance at the museum rose only slightly, and the gift shop's income doubled as a result.","Free entry on weekends doubled both the number of visitors to the museum and the money that it made from its gift shop.","Once weekend entry became free, twice as many people visited the museum, though the gift shop earned about the same as before."],"a":3,"ex":"במקור: מספר המבקרים הוכפל אחרי שהכניסה בסופי שבוע נעשתה חינם, אבל ההכנסה מחנות המתנות כמעט לא השתנתה («barely changed»). התשובה הנכונה: «twice as many people» ו-«earned about the same». התשובה עם «because its gift shop income had doubled» הופכת סיבה ותוצאה, התשובה עם «rose only slightly» משנה את המידה, והתשובה עם «doubled both» אומרת שגם ההכנסה הוכפלה.","w":[["attendance","מספר המבקרים, נוכחות"],["double","להכפיל, להיות כפול"],["barely","בקושי, כמעט לא"]]},{"q":"Few of the town's residents were aware of the new recycling rules until fines began to appear in their mailboxes.","o":["Most people in the town did not know about the new recycling rules before they started receiving fines by mail.","Most of the town's residents learned about the new recycling rules early, so very few of them ever received fines.","The town began sending fines because most residents had openly refused to follow the new recycling rules.","Few residents received any fines, even though most of them were not aware of the new recycling rules at all."],"a":0,"ex":"במקור: מעטים מהתושבים ידעו על כללי המחזור החדשים עד («until») שהתחילו להגיע קנסות לתיבות הדואר. כלומר רובם לא ידעו עד שקיבלו קנס, וזה מה שאומרת התשובה הנכונה. התשובה עם «learned ... early» הופכת את המשמעות, התשובה עם «openly refused» מוסיפה סיבה שאין במקור, והתשובה עם «Few residents received any fines» משנה את הכמות.","w":[["resident","תושב"],["be aware of","להיות מודע ל..."],["fine","קנס"]]}]},"x1rs2":{"id":"x1rs2","tier":1,"type":"rs","qs":[{"q":"Contrary to popular belief, camels do not store water in their humps; the humps are made mostly of fat, which the animals can use as energy when food is scarce.","o":["As most people believe, camels store water in their humps, and they use the fat in their bodies only when food is scarce.","A camel's hump is made mostly of water, which the animal is able to turn into fat when it cannot find enough food to eat.","Many people wrongly think a camel's hump holds water, but it mainly contains fat that serves as an energy source when food is hard to find.","Camels' humps contain both water and fat, so the animals are able to survive for months without any food or water at all."],"a":2,"ex":"במקור: בניגוד לאמונה הרווחת («Contrary to popular belief»), בדבשת אין מים אלא בעיקר שומן, שמשמש לאנרגיה כשאין מספיק מזון. התשובה הנכונה: «wrongly think» ו-«mainly contains fat». התשובה עם «As most people believe» הופכת את המשמעות, התשובה עם «made mostly of water» אומרת את ההפך, והתשובה עם «survive for months» מוסיפה טענה שאין במקור.","w":[["contrary to","בניגוד ל..."],["hump","דבשת"],["scarce","נדיר, חסר"]]},{"q":"The author's second novel sold far fewer copies than her first, yet critics consider it her finest work.","o":["Critics regard the author's second novel as her best book, even though it sold much less than her first one.","Critics consider the author's first novel her finest work, mainly because it sold far more copies than her second.","The author's second novel sold slightly better than her first one, and critics agree that it is her finest work.","Because critics disliked the author's second novel, it sold far fewer copies than her highly praised first book."],"a":0,"ex":"במקור: הרומן השני נמכר הרבה פחות מהראשון, ובכל זאת («yet») המבקרים רואים בו את היצירה הטובה ביותר שלה. התשובה הנכונה שומרת על שני החלקים («regard ... as her best book», «sold much less»). התשובה עם «first novel her finest work» מחליפה בין הספרים, התשובה עם «sold slightly better» הופכת את נתון המכירות, והתשובה עם «Because critics disliked» הופכת את דעת המבקרים ומוסיפה סיבה.","w":[["yet","ובכל זאת, אך"],["critic","מבקר"],["regard as","לראות כ..., להחשיב כ..."]]},{"q":"Unless the factory reduces its emissions by the end of the year, the government will withdraw its operating license.","o":["The government has already withdrawn the factory's license because it failed to reduce its emissions last year.","If the factory reduces its emissions by the end of the year, the government will give it a larger operating license.","The factory will keep its license whether or not it reduces its emissions, as long as it pays a fine this year.","The factory will lose its operating license if it has not cut its emissions by the time the year ends."],"a":3,"ex":"«Unless» = אלא אם כן. במקור: אם המפעל לא יפחית את הפליטות עד סוף השנה, הוא יאבד את הרישיון. התשובה הנכונה אומרת את אותו תנאי עם «if it has not cut». התשובה עם «has already withdrawn» אומרת שזה כבר קרה, התשובה עם «a larger operating license» מוסיפה פרס שאין במקור, והתשובה עם «whether or not» מבטלת את התנאי.","w":[["unless","אלא אם כן"],["emissions","פליטות (מזהמים)"],["withdraw","לשלול, למשוך"]]}]},"x1rs3":{"id":"x1rs3","tier":1,"type":"rs","qs":[{"q":"Children who learn a second language before the age of ten are more likely to speak it without a foreign accent than those who start later.","o":["Children who start learning a second language after age ten usually speak it without a foreign accent, unlike younger learners.","Children who learn a second language before age ten always speak it perfectly, while older learners can never lose their accent.","Children who speak a second language without an accent tend to start learning additional languages before the age of ten.","Starting a second language before age ten increases a child's chances of speaking it with no foreign accent, compared to starting later."],"a":3,"ex":"במקור: ילדים שמתחילים שפה שנייה לפני גיל עשר נוטים יותר («more likely») לדבר אותה בלי מבטא זר. התשובה הנכונה: «increases a child's chances». התשובה עם «after age ten» הופכת את הקבוצות, התשובה עם «always» ו-«never» משנה סיכוי לוודאות, והתשובה עם «tend to start learning additional languages» הופכת סיבה ותוצאה.","w":[["be likely to","צפוי ל..., סביר ש..."],["accent","מבטא"],["compared to","בהשוואה ל..."]]},{"q":"The bridge was designed to withstand earthquakes far stronger than any that have been recorded in the region so far.","o":["The bridge was badly damaged by an earthquake that was far stronger than any earlier one recorded in the region.","The bridge was built to survive earthquakes much more powerful than the strongest ones ever measured in the area.","The bridge can withstand only earthquakes that are weaker than the ones that have already been recorded in the region.","Engineers designed the bridge only after the region had recorded a long series of unusually strong earthquakes."],"a":1,"ex":"«withstand» = לעמוד בפני. במקור: הגשר תוכנן לעמוד ברעידות אדמה חזקות בהרבה מכל רעידה שנמדדה באזור עד היום. התשובה הנכונה: «survive» ו-«more powerful than the strongest ones». התשובה עם «badly damaged» אומרת שהגשר נפגע, התשובה עם «only ... weaker» הופכת את המידה, והתשובה עם «only after» מוסיפה סיבה שאין במקור.","w":[["withstand","לעמוד בפני, לשרוד"],["record","לתעד, לרשום"],["region","אזור"]]},{"q":"Rather than banning mobile phones in class, some schools now teach students how to use them as learning tools.","o":["Some schools have banned mobile phones in class because students used them as learning tools far too rarely.","Most schools now teach students to use mobile phones as learning tools, and they have also banned them in class.","Instead of forbidding phones in the classroom, some schools are now showing students how to use them for learning.","Some schools now teach students how to learn well without mobile phones, which have been banned from all classes."],"a":2,"ex":"«Rather than» = במקום. במקור: במקום לאסור טלפונים בכיתה, חלק מבתי הספר מלמדים להשתמש בהם ללמידה. התשובה הנכונה: «Instead of forbidding». התשובה עם «have banned ... because» הופכת את המשמעות ומוסיפה סיבה, התשובה עם «Most schools» משנה את הכמות ואומרת שגם אסרו, והתשובה עם «without mobile phones» אומרת את ההפך.","w":[["rather than","במקום, ולא"],["ban","לאסור"],["forbid","לאסור"]]}]},"x1rs4":{"id":"x1rs4","tier":1,"type":"rs","qs":[{"q":"The disease spread quickly through the city mainly because its early symptoms were so mild that few people sought medical help.","o":["The disease spread rapidly in the city chiefly because its first signs were so slight that hardly anyone saw a doctor.","The disease spread slowly through the city because people with even mild symptoms went to the doctor immediately.","Because so many people sought medical help, the city's busy doctors failed to notice the mild early symptoms of the disease.","The disease spread quickly through the city, even though its early symptoms were so severe that most people sought help."],"a":0,"ex":"במקור: המחלה התפשטה מהר בעיקר («mainly») כי התסמינים הראשונים היו קלים, ולכן מעטים פנו לעזרה רפואית. התשובה הנכונה: «chiefly because» ו-«hardly anyone saw a doctor». התשובה עם «spread slowly» הופכת את התוצאה, התשובה עם «so many people sought medical help» הופכת את הכמות, והתשובה עם «so severe» הופכת את חומרת התסמינים.","w":[["symptom","תסמין"],["mild","קל, מתון"],["seek","לחפש, לבקש (sought בעבר)"]]},{"q":"Only after the company had lost nearly half its customers did its managers admit that the new software was the problem.","o":["The company lost nearly half its customers because its managers refused to install the new software in time.","The managers admitted that the new software was the problem, and as a result they won back half their customers.","The company's managers did not admit that the new software was to blame until almost half the customers had left.","As soon as the new software was introduced, the managers admitted it was a problem, so only a few customers left."],"a":2,"ex":"«Only after» = רק אחרי. במקור: המנהלים הודו שהתוכנה החדשה היא הבעיה רק אחרי שהחברה איבדה כמעט חצי מהלקוחות. התשובה הנכונה: «did not admit ... until». התשובה עם «refused to install» הופכת את הבעיה, התשובה עם «won back half» מוסיפה תוצאה שאין במקור, והתשובה עם «As soon as» משנה את סדר הזמנים.","w":[["admit","להודות"],["to blame","אשם, האחראי"],["nearly","כמעט"]]},{"q":"While solar panels have become much cheaper over the past decade, the cost of storing the energy they produce remains high.","o":["Both solar panels and the storage of the energy they produce have become much cheaper over the past decade.","Solar panels have dropped greatly in price in the past ten years, but keeping the energy they generate is still expensive.","Solar panels have become more expensive over the past decade because storing the energy they produce costs so much.","Over the past decade, the cost of storing solar energy has fallen even faster than the price of the panels themselves."],"a":1,"ex":"«While» כאן = בעוד ש, ומציג ניגוד. במקור: הפאנלים הסולאריים הוזלו מאוד, אבל אחסון האנרגיה עדיין יקר. התשובה הנכונה: «dropped greatly in price» ו-«still expensive». התשובה עם «Both» אומרת שגם האחסון הוזל, התשובה עם «more expensive» הופכת את המחיר, והתשובה עם «has fallen even faster» אומרת שהאחסון הוזל.","w":[["while","בעוד ש...; כל עוד"],["storage","אחסון"],["remain","להישאר"]]}]},"x1rs5":{"id":"x1rs5","tier":1,"type":"rs","qs":[{"q":"Most of the ancient city's population left within a few decades, probably because a long drought destroyed the crops on which it depended.","o":["A long drought destroyed the ancient city's crops, but historians are certain that its population did not leave the city.","The ancient city's population left slowly over several centuries, and researchers are sure that war was the main cause.","A long drought that ruined the crops people relied on probably explains why most residents abandoned the city within decades.","Because most of the population had left the ancient city, nobody remained to water the crops during the long drought."],"a":2,"ex":"במקור: רוב התושבים עזבו תוך כמה עשורים, כנראה («probably») בגלל בצורת ארוכה שהרסה את היבולים. התשובה הנכונה: «probably explains why» ו-«abandoned the city». התשובה עם «did not leave» הופכת את העובדה, התשובה עם «several centuries» ו-«war» משנה גם את הזמן וגם את הסיבה, והתשובה עם «Because most of the population had left» הופכת סיבה ותוצאה.","w":[["drought","בצורת"],["crop","יבול"],["depend on","להיות תלוי ב..."]]},{"q":"The more time employees spend in meetings, the less satisfied they tend to be with their jobs, according to a recent survey.","o":["A recent survey found that employees who are satisfied with their jobs usually ask their managers for more meetings.","According to a recent survey, employees who spend more time in meetings tend to enjoy their jobs a great deal more.","A recent survey found that the time spent in meetings has no effect on how satisfied employees are with their jobs.","A recent survey found that workers' job satisfaction generally falls as the hours they spend in meetings rise."],"a":3,"ex":"המבנה «The more ..., the less ...» = ככל ש... יותר, כך... פחות. במקור: ככל שעובדים מבלים יותר זמן בישיבות, הם פחות מרוצים מהעבודה. התשובה הנכונה: «satisfaction ... falls as the hours ... rise». התשובה עם «ask ... for more meetings» הופכת את הקשר ומוסיפה טענה, התשובה עם «enjoy their jobs ... more» הופכת את הכיוון, והתשובה עם «no effect» מבטלת את הקשר.","w":[["satisfied","מרוצה"],["tend to","נוטה ל..."],["survey","סקר"]]},{"q":"The town's old textile mill, once its largest employer, has been turned into a museum that attracts thousands of tourists every year.","o":["The town's old textile mill is still its largest employer, and it also runs a small museum for the tourists who visit.","Each year thousands of tourists visit a museum in the old textile mill, which used to employ more people than any other business in town.","The town built a new textile mill next to the museum because thousands of tourists come to visit the museum every year.","The museum in the old textile mill attracts only a few hundred tourists a year, although the mill was once the town's largest employer."],"a":1,"ex":"במקור: מפעל הטקסטיל הישן, שפעם («once») היה המעסיק הגדול ביותר בעיר, הפך למוזיאון שמושך אלפי תיירים בשנה. התשובה הנכונה: «used to employ more people than any other business». התשובה עם «still its largest employer» אומרת שהמפעל עדיין פועל, התשובה עם «built a new textile mill» מוסיפה טענה שאין במקור, והתשובה עם «only a few hundred» משנה את המספר.","w":[["once","פעם, בעבר"],["employer","מעסיק"],["attract","למשוך"]]}]},"x1rs6":{"id":"x1rs6","tier":1,"type":"rs","qs":[{"q":"Despite repeated warnings from scientists, the fishing fleet continued to catch cod at such a rate that the population eventually collapsed.","o":["Scientists warned again and again, but the fleet kept fishing for cod so heavily that their numbers finally crashed.","Because scientists warned the fishing fleet in time, the cod population was able to recover before it could collapse.","The cod population collapsed because of a disease, even though the fishing fleet stopped catching cod as scientists had advised.","Scientists warned the fishing fleet only once, and as a result the number of cod in the area fell slightly."],"a":0,"ex":"במקור: למרות («Despite») אזהרות חוזרות של מדענים, הצי המשיך לדוג בקלה בקצב כזה שהאוכלוסייה קרסה לבסוף. התשובה הנכונה: «warned again and again» ו-«finally crashed». התשובה עם «recover» הופכת את התוצאה, התשובה עם «because of a disease» מוסיפה סיבה אחרת ואומרת שהדיג נעצר, והתשובה עם «only once» ו-«fell slightly» משנה את הכמות ואת המידה.","w":[["despite","למרות (+שם עצם)"],["repeated","חוזר ונשנה"],["collapse","לקרוס"]]},{"q":"Horses had disappeared from the Americas thousands of years before European explorers brought them back about five hundred years ago.","o":["About five hundred years ago, European explorers found that horses had lived in the Americas for thousands of years.","Horses had been gone from the Americas for thousands of years when European explorers reintroduced them about five centuries ago.","Horses disappeared from the Americas about five hundred years ago, shortly after the first European explorers arrived.","About five hundred years ago, European explorers took the last horses out of the Americas and shipped them to Europe."],"a":1,"ex":"במקור: סוסים נעלמו מאמריקה אלפי שנים לפני שחוקרים אירופים החזירו אותם, לפני כחמש מאות שנה. התשובה הנכונה: «had been gone ... for thousands of years» ו-«reintroduced them» (הכניסו אותם מחדש) «about five centuries ago». התשובה עם «had lived ... for thousands of years» אומרת שהסוסים היו שם כל הזמן, התשובה עם «disappeared ... about five hundred years ago» משנה את זמן ההיעלמות, והתשובה עם «took the last horses out» הופכת את כיוון התנועה.","w":[["disappear","להיעלם"],["vanish","להיעלם"],["explorer","חוקר, מגלה ארצות"]]},{"q":"Scientists still do not fully understand why some people remember their dreams clearly while others rarely recall them at all.","o":["Scientists have discovered exactly why some people remember their dreams clearly and others do not remember them.","Scientists believe that people who remember their dreams clearly also tend to sleep much better than others do.","Most people rarely recall their dreams, but scientists have found that everyone can learn to remember them clearly.","Science has not yet fully explained why certain people recall their dreams in detail while others hardly ever do."],"a":3,"ex":"במקור: המדענים עדיין לא מבינים עד הסוף («not fully understand») למה יש אנשים שזוכרים חלומות היטב ואחרים כמעט לא. התשובה הנכונה: «has not yet fully explained». התשובה עם «discovered exactly why» הופכת את המשמעות, התשובה עם «sleep much better» מוסיפה טענה שאין במקור, והתשובה עם «everyone can learn» מוסיפה ממצא שלא הוזכר.","w":[["recall","להיזכר, לזכור"],["rarely","לעיתים רחוקות"],["fully","לגמרי, במלואו"]]}]},"x1rc1":{"id":"x1rc1","tier":1,"type":"rc","title":"Selling Winter to the Tropics","text":["In the early 1800s, a young Boston businessman named Frederic Tudor had an idea that most of his neighbors found ridiculous. Every winter, the ponds around Boston froze solid, and in spring the ice was simply left to melt. Tudor believed that people living in hot places, such as the islands of the Caribbean, would pay well for this frozen water if only it could reach them in good condition.","His first attempt, in 1806, was close to a disaster. He sent a ship loaded with ice to the island of Martinique, but there was nowhere on the island to store it, so much of it melted soon after it arrived, and the people who saw the rest had no idea what to do with it. Tudor lost a large amount of money, and in the following years his debts became so serious that he was arrested more than once. Yet he refused to give up.","Over the next two decades, Tudor and his partners solved the trade's practical problems one by one. They learned to pack the ice in sawdust, a cheap waste product of local sawmills, which slowed melting dramatically. They built thick-walled storehouses at their destinations so that the ice could be kept for months. A new tool pulled by horses cut the frozen ponds into blocks of identical size, which could be stacked tightly and loaded quickly. By 1833, ice from Massachusetts was surviving a four-month voyage all the way to India.","Tudor also had to create demand for a product that customers had never needed. At first he gave ice away, showed bar owners how to serve cold drinks, and taught hospitals to use it to cool patients with fevers. Once people had grown used to cold drinks, few wanted to go back. The trade grew for decades, but it faded in the late nineteenth century, when machines that could produce ice anywhere made shipping it across oceans unnecessary."],"qs":[{"q":"Which of the following is the best title for the passage?","o":["How Machines Made Ice Cheap","Why Boston's Ponds Freeze Every Winter","The Rise and Fall of a Trade in Natural Ice","Life in a Debtors' Prison in the 1800s"],"a":2,"ex":"הקטע מספר את כל הסיפור של סחר הקרח: הרעיון של טיודור, הכישלון הראשון, הפתרונות שהפכו את הסחר להצלחה, ולבסוף הדעיכה («faded») כשמכונות התחילו לייצר קרח. «How Machines Made Ice Cheap» מתאר רק את המשפט האחרון, והמעצר בגלל חובות מוזכר רק בקצרה בפסקה 2.","w":[["rise and fall","עלייה ונפילה"],["trade","סחר, מסחר"]]},{"q":"According to paragraph 3, sawdust was used because it","o":["greatly slowed down the melting of the ice","made the blocks of ice the same size","was required by the owners of the ships","kept the ice clean enough to drink"],"a":0,"ex":"בפסקה 3 כתוב שאריזת הקרח בנסורת «slowed melting dramatically», כלומר האטה מאוד את ההמסה. את הבלוקים בגודל זהה ייצר כלי חיתוך שנמשך על ידי סוסים, ולא הנסורת.","w":[["sawdust","נסורת"],["dramatically","באופן דרמטי, מאוד"],["melt","להימס"]]},{"q":"In paragraph 4, the word \"faded\" (in \"it faded in the late nineteenth century\") is closest in meaning to","o":["suddenly expanded","changed direction","became illegal","gradually declined"],"a":3,"ex":"«fade» כאן = לדעוך, להיחלש בהדרגה. המשפט מסביר שמכונות שמייצרות קרח בכל מקום הפכו את משלוח הקרח למיותר, ולכן הסחר נחלש. «suddenly expanded» (התרחב פתאום) הפוך, ובקטע אין שום רמז לכך שהסחר נאסר («became illegal»).","w":[["fade","לדעוך, להתעמעם"],["decline","לרדת, לדעוך"],["unnecessary","מיותר, לא נחוץ"]]},{"q":"Why does the author mention that Tudor gave ice away at first (paragraph 4)?","o":["To show that he was no longer interested in making money","To show how he created demand for a product people had not used before","To explain why he was arrested because of his debts","To show that ice was very cheap to produce in hospitals"],"a":1,"ex":"הפסקה נפתחת ב-«Tudor also had to create demand», כלומר היה עליו ליצור ביקוש למוצר שאנשים לא היו צריכים קודם. חלוקת קרח בחינם הייתה דרך לגרום לאנשים להתרגל אליו. היא לא מראה שהוא הפסיק להתעניין ברווח, כי המטרה הייתה שבהמשך יקנו ממנו.","w":[["demand","ביקוש"],["give away","לחלק בחינם"]]},{"q":"Which of the following is NOT mentioned as a way that Tudor and his partners improved the ice trade?","o":["Packing the ice in sawdust","Building thick-walled storehouses","Cutting the ice into blocks of equal size","Producing ice with machines"],"a":3,"ex":"שלוש הדרכים האחרות מופיעות בפסקה 3: נסורת, מחסנים עם קירות עבים, וחיתוך לבלוקים בגודל זהה. מכונות לייצור קרח מוזכרות רק בסוף פסקה 4, והן מה שגרם לסחר של טיודור לדעוך, לא דרך לשפר אותו.","w":[["improve","לשפר"],["storehouse","מחסן"]]}]},"x1rc2":{"id":"x1rc2","tier":1,"type":"rc","title":"Paths Nobody Planned","text":["Walk across almost any university campus or city park and you will probably notice narrow strips of bare earth cutting across the grass. Planners call them \"desire lines\" or \"desire paths.\" They are created not by designers but by thousands of ordinary people who, one step at a time, choose a route that is shorter or more convenient than the official path.","For a long time, such paths were treated as a sign of bad behavior. Park managers put up fences, planted thick bushes, and posted signs asking visitors to stay on the paved walkways. These efforts rarely worked for long. If a shortcut saved people enough time, they usually found a way around the obstacle, and sometimes the fence itself became the starting point of a new path.","In recent decades, some planners have begun to view desire paths differently, seeing them as free and honest information about how people actually move. Instead of guessing where walkways should go, a few universities have opened new buildings surrounded only by grass. After several months, they examine where students have worn the ground down and pave those routes. In some northern cities, planners carry out a similar study each winter by observing which lines of footprints appear first in fresh snow.","Not every desire path deserves to become permanent, however. Some cross areas where plants or nesting birds need protection, and others lead people straight into dangerous traffic. The challenge for planners is to tell the difference between a path that reveals a real need and one that simply reflects a careless habit. Even so, many of them now agree that it is wiser to listen to people's feet than to fight them."],"qs":[{"q":"The passage mainly discusses","o":["why fences are the most effective way to protect public parks","how informal walking routes are formed and how planners respond to them","the history of paved walkways on university campuses","the dangers that pedestrians face in heavy city traffic"],"a":1,"ex":"הקטע מסביר מה הם «desire paths» ואיך הם נוצרים (פסקה 1), איך מתכננים ניסו להילחם בהם (פסקה 2), איך חלקם לומדים מהם היום (פסקה 3), ואילו שבילים לא כדאי לשמר (פסקה 4). לגבי גדרות הקטע אומר דווקא שהן כמעט לא עבדו, והסכנה בתנועה מוזכרת רק כדוגמה אחת בפסקה 4.","w":[["informal","לא רשמי"],["respond to","להגיב ל..."]]},{"q":"According to paragraph 2, the fences that were built to stop people from using shortcuts","o":["were removed by planners every winter","were welcomed by most visitors","were often ineffective","caused harm to nesting birds"],"a":2,"ex":"בפסקה 2 כתוב «These efforts rarely worked for long», ואנשים מצאו דרך לעקוף את המכשול, ולפעמים הגדר עצמה הפכה לתחילת שביל חדש. כלומר הגדרות לא היו יעילות. ציפורים מקננות מוזכרות רק בפסקה 4 ולא בהקשר של גדרות.","w":[["ineffective","לא יעיל"],["obstacle","מכשול"],["shortcut","קיצור דרך"]]},{"q":"The author mentions fresh snow in paragraph 3 in order to","o":["give another example of how planners learn where people want to walk","explain why desire paths disappear during the winter","show that northern cities have fewer parks than other cities","describe a danger that walkers face in cold weather"],"a":0,"ex":"המשפט על השלג מתחיל ב-«a similar study», כלומר זו עוד דוגמה, בדומה לאוניברסיטאות שמחכות לראות איפה הסטודנטים הולכים: המתכננים בודקים אילו עקבות מופיעות ראשונות בשלג כדי לדעת איפה אנשים רוצים ללכת. אין בקטע טענה שהשבילים נעלמים בחורף או שהשלג מסוכן.","w":[["in order to","כדי ל... (+פועל)"],["observe","לצפות, להתבונן"],["footprint","עקבה, טביעת רגל"]]},{"q":"In paragraph 4, the phrase \"listen to people's feet\" means","o":["ask walkers to fill out a survey about the park","build quieter walkways in busy areas","fine people who leave the official path","pay attention to the routes people actually choose"],"a":3,"ex":"זה ביטוי ציורי: «להקשיב לרגליים» של אנשים פירושו לשים לב לאן הם באמת הולכים, כמו המתכננים בפסקה 3 שסוללים את המסלולים שהסטודנטים בחרו. זה ההפך מ-«fight them», כלומר מניסיון לעצור אותם בגדרות ובשלטים. קנסות («fine people») הם בדיוק סוג של מלחמה בהם.","w":[["phrase","ביטוי"],["pay attention to","לשים לב ל..."]]},{"q":"It can be inferred from paragraph 4 that the author believes","o":["each desire path should be judged on its own before it is paved","all desire paths should be paved as soon as possible","desire paths are always a sign of careless behavior","nesting birds create most of the desire paths in parks"],"a":0,"ex":"בפסקה 4 הכותב אומר שלא כל שביל ראוי להיות קבוע («Not every desire path deserves to become permanent»), ושהאתגר הוא להבחין בין שביל שמגלה צורך אמיתי לבין הרגל רשלני. מכאן שצריך לבדוק כל שביל לגופו. «as soon as possible» סותר את ההסתייגות הזאת, ו-«always» סותר את הטענה שחלק מהשבילים מגלים צורך אמיתי.","w":[["infer","להסיק"],["permanent","קבוע"],["reveal","לגלות, לחשוף"]]}]},"x1rc3":{"id":"x1rc3","tier":1,"type":"rc","title":"Nobody Is Watching as Closely as You Think","text":["Imagine spilling coffee on your shirt just before an important meeting. For the rest of the day, you may feel that everyone is staring at the stain. Psychologists have a name for this feeling: the spotlight effect. It refers to our tendency to overestimate how much other people notice our appearance and our behavior, as if we were always standing on a brightly lit stage.","In a well-known experiment, researchers at Cornell University asked students to put on a T-shirt printed with the face of a singer whom most of them considered deeply unfashionable. Each student then entered a room where other students were filling out a questionnaire, stayed briefly, and left. Afterwards, the wearers guessed that about half of the people in the room had noticed the shirt. In fact, only about a quarter had.","Why do we make this mistake? One explanation is that we are, quite naturally, the center of our own experience. We know every detail of our own appearance and feel our embarrassment strongly, so we find it hard to imagine that others are not equally aware of it. We forget that the people around us are busy with their own concerns, and many of them are probably worrying about how they themselves look.","Understanding the spotlight effect can be surprisingly useful. People who are afraid of making a small mistake in public, such as forgetting a word during a speech, often suffer more from the fear than from the mistake itself. Knowing that most listeners will barely notice, or will quickly forget, may make it easier to take part in class discussions, try a new activity, or simply walk into a room with greater confidence."],"qs":[{"q":"The main purpose of the passage is to","o":["explain a common error in how people think others see them","teach readers how to remove stains before a meeting","show that most students dislike unfashionable clothing","argue that people should care more about their appearance"],"a":0,"ex":"כל הקטע עוסק ב-«spotlight effect»: הנטייה להעריך יתר על המידה כמה אחרים שמים לב אלינו. הוא מגדיר את התופעה, מביא ניסוי, מסביר את הסיבה ומראה למה כדאי להכיר אותה. הכתם על החולצה הוא רק דוגמה בפתיחה, והקטע דווקא מעודד לדאוג פחות למראה, לא יותר.","w":[["purpose","מטרה"],["common","נפוץ"]]},{"q":"According to paragraph 2, the students who wore the T-shirt","o":["were asked to fill out a questionnaire about singers","were noticed by about half of the people in the room","chose that T-shirt because they liked the singer","believed that more people had noticed it than really had"],"a":3,"ex":"בפסקה 2 כתוב שהלובשים העריכו שבערך חצי מהאנשים בחדר שמו לב לחולצה, אבל בפועל («In fact») רק כרבע שמו לב. «noticed by about half» הוא הניחוש שלהם, לא המציאות. את השאלון מילאו האנשים שישבו בחדר, לא לובשי החולצה.","w":[["notice","להבחין, לשים לב"],["questionnaire","שאלון"],["in fact","למעשה, בפועל"]]},{"q":"In paragraph 1, the word \"overestimate\" is closest in meaning to","o":["think that something is smaller than it really is","think that something is greater than it really is","measure something exactly","refuse to consider something"],"a":1,"ex":"«overestimate» = להעריך יתר על המידה (over = יותר מדי, estimate = להעריך). הקטע מסביר שאנחנו חושבים שאחרים שמים לב אלינו יותר ממה שהם באמת שמים לב. «think that something is smaller» הוא בדיוק ההפך, underestimate.","w":[["overestimate","להעריך יתר על המידה"],["estimate","להעריך (כמות)"],["appearance","מראה חיצוני"]]},{"q":"According to paragraph 3, one reason for the spotlight effect is that","o":["other people are usually very critical of us","we rarely think about how we look to others","we are very aware of our own appearance and feelings","the people around us notice every small detail"],"a":2,"ex":"בפסקה 3 כתוב שאנחנו מכירים כל פרט במראה שלנו ומרגישים את המבוכה שלנו בעוצמה, ולכן קשה לנו לדמיין שאחרים לא מודעים לזה באותה מידה. «the people around us notice every small detail» סותר את הפסקה, שאומרת שהאחרים עסוקים בעניינים שלהם.","w":[["aware of","מודע ל..."],["embarrassment","מבוכה"],["concern","דאגה, עניין"]]},{"q":"Which of the following can be inferred from paragraph 4?","o":["Most speakers forget at least one word during every speech.","Listeners usually remember small mistakes for a long time.","The fear of embarrassment may stop people from doing things they would enjoy.","Class discussions make students more afraid of making mistakes."],"a":2,"ex":"בפסקה 4 כתוב שהבנת התופעה יכולה להקל על השתתפות בדיון בכיתה, על ניסיון של פעילות חדשה ועל כניסה לחדר בביטחון. מכאן אפשר להסיק שהפחד ממבוכה מונע מאנשים לעשות דברים כאלה. «remember small mistakes for a long time» סותר את הטענה שהמאזינים ישכחו מהר («quickly forget»).","w":[["infer","להסיק"],["confidence","ביטחון עצמי"],["barely","בקושי"]]}]},"x2sc1":{"id":"x2sc1","tier":2,"type":"sc","qs":[{"q":"Independent laboratories were unable to ___ the company's claim that its new battery could be fully recharged in under five minutes, so the product's launch was postponed until further tests could be carried out.","o":["undermine","anticipate","corroborate","retract"],"a":2,"ex":"«corroborate» = לאשש, לאשר בעזרת ראיות נוספות. המעבדות לא הצליחו לאשר את הטענה, ולכן ההשקה נדחתה עד לבדיקות נוספות. «undermine» (לערער) לא מתאים: אם המעבדות לא הצליחו לערער את הטענה, לא הייתה סיבה לדחות את ההשקה. «retract» (לחזור בו) הוא משהו שרק החברה עצמה יכולה לעשות לטענה שלה.","w":[["corroborate","לאשש, לאמת"],["undermine","לערער, לחתור תחת"],["postpone","לדחות (למועד מאוחר יותר)"]]},{"q":"The new bridge was expected to ease congestion in the old town; ___, traffic there has actually grown since it opened, because drivers now use the area as a shortcut.","o":["ironically","consequently","similarly","in addition"],"a":0,"ex":"«ironically» = באופן אירוני, דווקא ההפך ממה שציפו. ציפו שהגשר יקל על העומס, ובפועל התנועה גדלה. «consequently» (כתוצאה מכך) היה אומר שהגידול בתנועה נובע מהציפייה להקלה, וזה לא הגיוני. «similarly» (באופן דומה) לא מתאים, כי אין כאן שני דברים דומים אלא ניגוד.","w":[["ironically","באופן אירוני, דווקא"],["consequently","כתוצאה מכך"],["congestion","עומס (תנועה)"]]},{"q":"Because the symptoms of the disease are so ___, appearing in one patient as a mild rash and in another as severe joint pain, doctors often fail to diagnose it for months.","o":["conspicuous","uniform","acute","variable"],"a":3,"ex":"«variable» = משתנה, לא קבוע. אצל מטופל אחד יש פריחה קלה ואצל אחר כאבי מפרקים קשים, כלומר התסמינים משתנים מאדם לאדם, ולכן קשה לאבחן את המחלה. «conspicuous» (בולט לעין) היה דווקא מקל על האבחון, ו-«uniform» (אחיד) אומר את ההפך מהדוגמה שבמשפט.","w":[["variable","משתנה, לא קבוע"],["conspicuous","בולט, נראה לעין"],["diagnose","לאבחן"]]},{"q":"___ the director's public promise to return the stolen statue, it remained on display in the museum for another decade.","o":["Owing to","Notwithstanding","In accordance with","On behalf of"],"a":1,"ex":"«notwithstanding» = למרות, חרף. המנהל הבטיח בפומבי להחזיר את הפסל, ובכל זאת הפסל נשאר בתצוגה עוד עשור, כלומר יש כאן ניגוד. «owing to» (בגלל) היה הופך את ההבטחה לסיבה להשארת הפסל, וזה לא הגיוני. «in accordance with» (בהתאם ל...) היה אומר שהפסל נשאר כפי שהובטח, וזה ההפך מההבטחה.","w":[["notwithstanding","למרות, חרף"],["owing to","בגלל, עקב"],["on display","מוצג (לקהל)"]]}]},"x2sc2":{"id":"x2sc2","tier":2,"type":"sc","qs":[{"q":"The minister's sudden resignation, coming only days before the budget vote, threatened to ___ months of careful negotiations between the coalition partners.","o":["finalize","derail","reinforce","commemorate"],"a":1,"ex":"«derail» = להוריד מהפסים, לסכל. התפטרות פתאומית ימים ספורים לפני ההצבעה מאיימת להרוס חודשים של משא ומתן. «threatened to» מעיד על משהו שלילי, ולכן «reinforce» (לחזק) ו-«finalize» (להשלים, לסגור סופית) לא מתאימים, כי הם תוצאות חיוביות.","w":[["derail","לסכל, להוריד מהפסים"],["resignation","התפטרות"],["reinforce","לחזק"]]},{"q":"The two research teams worked entirely ___, which makes it all the more striking that they reached almost identical conclusions.","o":["jointly","reluctantly","simultaneously","independently"],"a":3,"ex":"«independently» = באופן עצמאי, בנפרד זה מזה. דווקא העובדה שהצוותים לא עבדו יחד הופכת את המסקנות הזהות למפתיעות. «jointly» (במשותף) היה הופך את הדמיון במסקנות למובן מאליו. «simultaneously» (בו-זמנית) מפתה, אבל עבודה באותו זמן לא מסבירה למה הדמיון מפתיע.","w":[["independently","באופן עצמאי, בנפרד"],["jointly","במשותף, ביחד"],["striking","בולט, מפתיע"]]},{"q":"The drug is highly effective against the infection; ___, its side effects are so severe that doctors prescribe it only as a last resort.","o":["nonetheless","accordingly","in other words","for instance"],"a":0,"ex":"«nonetheless» = אף על פי כן, ובכל זאת. התרופה יעילה מאוד, אבל תופעות הלוואי קשות ולכן נותנים אותה רק כמוצא אחרון, כלומר ניגוד. «in other words» (במילים אחרות) היה מציג את תופעות הלוואי כניסוח אחר של היעילות, וזה לא נכון. «accordingly» (בהתאם לכך) יוצר קשר של סיבה ותוצאה שאין כאן.","w":[["nonetheless","אף על פי כן, ובכל זאת"],["last resort","מוצא אחרון"],["prescribe","לרשום (תרופה)"]]},{"q":"When the new mayor took office, the city was on the ___ of bankruptcy, with barely enough money left to pay its employees' salaries.","o":["peak","core","verge","surface"],"a":2,"ex":"«on the verge of» = על סף. בקושי נשאר כסף למשכורות, כלומר העירייה הייתה קרובה מאוד לפשיטת רגל. «peak» (שיא) מפתה, אבל «on the peak of bankruptcy» אינו צירוף תקין באנגלית, ושיא מתאים בדרך כלל להצלחה ולא לקריסה.","w":[["on the verge of","על סף"],["bankruptcy","פשיטת רגל"],["take office","להיכנס לתפקיד"]]}]},"x2sc3":{"id":"x2sc3","tier":2,"type":"sc","qs":[{"q":"The species was believed to have died out in the 1930s; ___, when a small population was discovered on a remote island in 2019, biologists were astonished.","o":["thus","whereas","otherwise","meanwhile"],"a":0,"ex":"«thus» = לכן, כך ש... מכיוון שחשבו שהמין נכחד כבר בשנות ה-30, הגילוי ב-2019 הדהים את הביולוגים, כלומר סיבה ותוצאה. «whereas» (בעוד ש) משווה בין שני נושאים מנוגדים, ו-«otherwise» (אחרת) לא מתאים, כי אין כאן תנאי.","w":[["thus","לכן, כך"],["die out","להיכחד"],["astonished","נדהם"]]},{"q":"Her reputation as a ___ negotiator was well deserved: she rarely made a concession without obtaining something of greater value in return.","o":["naive","hesitant","shrewd","generous"],"a":2,"ex":"«shrewd» = ממולח, פיקח וחד. היא כמעט אף פעם לא ויתרה על משהו בלי לקבל בתמורה משהו שווה יותר, וזו בדיוק התנהגות של מנהלת משא ומתן חכמה. «naive» (תמימה) ו-«generous» (נדיבה) אומרים כמעט את ההפך, כי מי שנדיבה מוותרת בלי לדרוש תמורה.","w":[["shrewd","ממולח, פיקח"],["concession","ויתור"],["naive","תמים"]]},{"q":"Rather than ___ the protesters' demands, the government chose to ignore them, hoping that the movement would lose momentum over the summer.","o":["dismiss","address","overlook","imitate"],"a":1,"ex":"«address» = לטפל ב..., להתייחס ברצינות ל... «rather than» יוצר ניגוד בין מה שהממשלה לא עשתה לבין מה שעשתה (התעלמה), ולכן צריך פועל שהוא ההפך מהתעלמות. «dismiss» (לבטל, לדחות) ו-«overlook» (להתעלם) דומים ל-«ignore», ואז אין כאן ניגוד.","w":[["address","לטפל ב..., להתייחס ל..."],["dismiss","לבטל, לדחות"],["momentum","תנופה"]]},{"q":"___ its small size, the device can store more data than the computers that filled entire rooms in the 1970s.","o":["Because of","Thanks to","Instead of","For all"],"a":3,"ex":"«for all» = למרות (כל ה...). המכשיר קטן, ובכל זאת שומר יותר מידע ממחשבים שמילאו חדרים שלמים, כלומר ניגוד. «because of» ו-«thanks to» (בזכות) הופכים את הגודל הקטן לסיבה ליכולת האחסון הגדולה, וזה לא הגיוני.","w":[["for all","למרות"],["store","לאחסן, לשמור"],["thanks to","בזכות"]]}]},"x2sc4":{"id":"x2sc4","tier":2,"type":"sc","qs":[{"q":"The instructions that came with the furniture were so ___ that even the store's own employees could not work out how the pieces fitted together.","o":["explicit","concise","durable","convoluted"],"a":3,"ex":"«convoluted» = מסובך ומפותל. אם אפילו עובדי החנות לא הבינו איך מרכיבים את הרהיט, ההוראות היו מסובכות מאוד. «explicit» (מפורש) ו-«concise» (תמציתי) הם תכונות של הוראות טובות, ולכן הם לא מסבירים למה איש לא הבין אותן.","w":[["convoluted","מסובך, מפותל"],["explicit","מפורש, ברור"],["work out","להבין, לפענח"]]},{"q":"Some economists argue that raising the minimum wage leads to job losses, ___ others maintain that it increases spending and therefore creates new jobs.","o":["so that","whereas","unless","because"],"a":1,"ex":"«whereas» = בעוד ש..., ואילו. המשפט מציג שתי עמדות מנוגדות של כלכלנים. «so that» (כדי ש) ו-«because» (מפני ש) יוצרים קשר של מטרה או סיבה בין שתי העמדות, וזה לא הגיוני. «unless» (אלא אם כן) הוא תנאי, ואין כאן תנאי.","w":[["whereas","בעוד ש..., ואילו"],["maintain","לטעון, לגרוס"],["minimum wage","שכר מינימום"]]},{"q":"The new regulations are intended to ___ the use of pesticides near rivers, not to ban it altogether.","o":["prohibit","encourage","curb","disguise"],"a":2,"ex":"«curb» = לרסן, להגביל. התקנות נועדו להגביל את השימוש בחומרי הדברה ולא לאסור אותו לגמרי. «prohibit» (לאסור) הוא בדיוק מה שהמשפט שולל («not to ban it»). «encourage» (לעודד) לא מתאים, כי אין סיבה לנגד בין עידוד לבין איסור, ותקנות ליד נהרות נועדו להגן עליהם.","w":[["curb","לרסן, להגביל"],["prohibit","לאסור"],["altogether","לגמרי, כליל"]]},{"q":"The village had been ___ abandoned by the 1950s; only a handful of elderly residents still lived among its empty houses.","o":["virtually","barely","recently","temporarily"],"a":0,"ex":"«virtually» = כמעט לגמרי, למעשה. רק קומץ תושבים קשישים נשארו בכפר, כלומר הוא ננטש כמעט לגמרי. «barely» (בקושי) היה אומר שכמעט אף אחד לא עזב, וזה ההפך. «temporarily» (באופן זמני) לא נתמך בשום דבר במשפט.","w":[["virtually","כמעט לגמרי, למעשה"],["abandon","לנטוש"],["a handful of","קומץ, מעט"]]}]},"x2sc5":{"id":"x2sc5","tier":2,"type":"sc","qs":[{"q":"Persistent ___ between the two ministries delayed the project for years, as each blamed the other for the rising costs.","o":["cooperation","harmony","friction","curiosity"],"a":2,"ex":"«friction» = חיכוך, מתיחות. כל משרד האשים את המשרד השני בעליית העלויות, וזה סימן למתיחות שעיכבה את הפרויקט. «cooperation» (שיתוף פעולה) ו-«harmony» (הרמוניה) אומרים את ההפך, והם לא היו גורמים לעיכוב.","w":[["friction","חיכוך, מתיחות"],["persistent","מתמשך, עיקש"],["blame","להאשים"]]},{"q":"The museum agreed to lend the painting to the exhibition ___ it would be kept at a constant temperature and protected from direct sunlight.","o":["so that","in case","now that","provided that"],"a":3,"ex":"«provided that» = בתנאי ש... המוזיאון הסכים להשאיל את הציור רק אם ישמרו עליו בטמפרטורה קבועה ויגנו עליו מאור שמש, כלומר תנאי. «so that» (כדי ש) הופך את השמירה על הציור למטרה של ההשאלה, וזה לא הגיוני. «now that» (עכשיו כש) מניח שהדבר כבר קורה, ולא מציב תנאי.","w":[["provided that","בתנאי ש..."],["lend","להשאיל"],["constant","קבוע"]]},{"q":"Although the new policy was presented as a temporary measure, many observers suspected that it would prove far more ___ than the government admitted.","o":["enduring","fleeting","transparent","affordable"],"a":0,"ex":"«enduring» = מתמשך, שנשאר לאורך זמן. «although» יוצר ניגוד ל-«temporary» (זמני), ולכן המשקיפים חשדו שהמדיניות תימשך הרבה יותר זמן ממה שהממשלה הודתה. «fleeting» (חולף, קצר) הוא בעצם «זמני», ולכן אין בו ניגוד.","w":[["enduring","מתמשך, עמיד"],["fleeting","חולף, קצר מועד"],["measure","צעד, אמצעי"]]},{"q":"The rescue team had to ___ the search at nightfall because the strong winds made it too dangerous to continue.","o":["intensify","suspend","launch","extend"],"a":1,"ex":"«suspend» = להשעות, להפסיק זמנית. הרוחות החזקות הפכו את המשך החיפוש למסוכן מדי, ולכן הצוות עצר אותו. «intensify» (להגביר) ו-«extend» (להאריך) אומרים את ההפך מעצירה, ו-«launch» (להתחיל) לא מתאים לחיפוש שכבר התנהל.","w":[["suspend","להשעות, להפסיק זמנית"],["intensify","להגביר, להעצים"],["nightfall","רדת הלילה"]]}]},"x2sc6":{"id":"x2sc6","tier":2,"type":"sc","qs":[{"q":"The factory has cut its water use by forty percent; ___, it now recycles almost all of its waste.","o":["nevertheless","moreover","otherwise","conversely"],"a":1,"ex":"«moreover» = יתר על כן. המפעל חסך במים וגם ממחזר כמעט את כל הפסולת, כלומר שני הישגים שמתווספים זה לזה. «nevertheless» (למרות זאת) ו-«conversely» (לעומת זאת) דורשים ניגוד, ואין כאן ניגוד בין שני ההישגים.","w":[["moreover","יתר על כן"],["recycle","למחזר"],["conversely","לעומת זאת, להפך"]]},{"q":"The senator's response to the scandal was deliberately ___; reporters left the press conference still unsure whether she intended to resign.","o":["ambiguous","decisive","sincere","emphatic"],"a":0,"ex":"«ambiguous» = דו-משמעי, לא חד. העיתונאים יצאו ממסיבת העיתונאים בלי לדעת אם היא מתכוונת להתפטר, ולכן התשובה שלה הייתה מעורפלת. «decisive» (החלטי) ו-«emphatic» (נחרץ) היו משאירים תמונה ברורה, וזה ההפך.","w":[["ambiguous","דו-משמעי, מעורפל"],["decisive","החלטי"],["resign","להתפטר"]]},{"q":"Few people outside the region had heard of the festival; ___, it attracted more than fifty thousand visitors in its first year.","o":["as a result","in short","that is","all the same"],"a":3,"ex":"«all the same» = בכל זאת, למרות זאת. מעטים הכירו את הפסטיבל, ובכל זאת הגיעו אליו יותר מחמישים אלף מבקרים, כלומר ניגוד. «as a result» (כתוצאה מכך) היה הופך את חוסר ההיכרות לסיבה להצלחה, וזה לא הגיוני. «that is» (כלומר) מציג הסבר, לא ניגוד.","w":[["all the same","בכל זאת, למרות זאת"],["attract","למשוך"],["in short","בקיצור"]]},{"q":"The expedition had to turn back after only three days because of a ___ of fresh water: two of their four tanks had leaked during the crossing.","o":["surplus","flood","shortage","source"],"a":2,"ex":"«shortage» = מחסור. שניים מארבעת המכלים דלפו, ולכן לא היו מספיק מים והמשלחת נאלצה לחזור. «surplus» (עודף) הוא ההפך, ועודף מים לא היה גורם למשלחת לחזור.","w":[["shortage","מחסור"],["surplus","עודף"],["leak","לדלוף"]]}]},"x2rs1":{"id":"x2rs1","tier":2,"type":"rs","qs":[{"q":"Although the new vaccine proved highly effective in clinical trials, its high cost and the need to store it at extremely low temperatures have limited its use in poorer countries.","o":["Because the new vaccine has been used less in poorer countries, its price has risen and it must now be stored at extremely low temperatures.","The new vaccine worked very well in trials, but because it is expensive and must be kept very cold, it has been used less in poorer countries.","The new vaccine proved less effective in trials than expected, which is why poorer countries have chosen not to buy it or store it.","Despite its high cost, the new vaccine is now widely used in poorer countries, since most of them can store it at very low temperatures."],"a":1,"ex":"המקור: החיסון היה יעיל מאוד בניסויים, אבל המחיר הגבוה והצורך לשמור אותו בקור קיצוני הגבילו את השימוש בו במדינות עניות. התשובה הנכונה אומרת אותו דבר («very well» במקום «highly effective», «kept very cold» במקום «store at extremely low temperatures»). אחת השגויות הופכת סיבה ותוצאה, אחרת אומרת שהחיסון היה פחות יעיל, והרביעית אומרת שהוא נמצא בשימוש נרחב, בניגוד למקור.","w":[["effective","יעיל"],["store","לאחסן, לשמור"],["limit","להגביל"]]},{"q":"It was not until the late nineteenth century that doctors widely accepted that many diseases are spread by germs, an idea that had been proposed decades earlier.","o":["In the late nineteenth century, doctors first proposed that many diseases are spread by germs, and the idea was widely accepted within a few decades.","Decades before the late nineteenth century, most doctors already accepted the idea that germs spread many diseases, but few of them could prove it.","Doctors in the late nineteenth century rejected the idea that germs spread disease, even though it had been widely accepted several decades earlier.","The idea that germs spread many diseases was suggested decades before most doctors finally came to accept it in the late nineteenth century."],"a":3,"ex":"«It was not until X that Y» = רק ב-X קרה Y. הרעיון שחיידקים מפיצים מחלות הוצע עשרות שנים קודם, אבל רוב הרופאים קיבלו אותו רק בסוף המאה ה-19. התשובה הנכונה שומרת על הסדר הזה. אחת השגויות אומרת שהרעיון רק הוצע בסוף המאה, אחרת אומרת שהרופאים כבר קיבלו אותו קודם, והרביעית אומרת שהם דחו אותו.","w":[["not until","רק כאשר, לא לפני"],["widely","באופן נרחב"],["propose","להציע"]]},{"q":"The more choices consumers are offered, the less satisfied they tend to be with whatever they finally decide to buy.","o":["Consumers who are given a wider range of options are generally less content with their eventual purchases.","Consumers who are offered more choices tend to buy more products, although they are usually less satisfied with each of them.","The less satisfied consumers are with their purchases, the more choices they demand the next time they decide to buy something.","Offering consumers fewer choices makes them less satisfied, because they feel that they have not been allowed to decide for themselves."],"a":0,"ex":"«The more X, the less Y» = ככל ש-X גדל, Y קטן. ככל שמציעים לצרכנים יותר אפשרויות, הם פחות מרוצים ממה שקנו בסוף. התשובה הנכונה אומרת זאת במילים אחרות («a wider range of options», «less content»). אחת השגויות מוסיפה שהם קונים יותר מוצרים, אחרת הופכת את כיוון הסיבה, והרביעית טוענת שפחות אפשרויות פוגעות בשביעות הרצון, וזה ההפך.","w":[["the more... the less","ככל ש... יותר, כך... פחות"],["satisfied","מרוצה"],["content","שבע רצון, מרוצה"]]}]},"x2rs2":{"id":"x2rs2","tier":2,"type":"rs","qs":[{"q":"Far from being a recent invention, the practice of sending children to summer camps dates back to the 1880s, when it was promoted as a cure for the supposed weakness of city children.","o":["Summer camps for children were invented quite recently, although the idea that city children are weak was first promoted in the 1880s.","In the 1880s, summer camps were criticized for making city children weaker, which is why they did not become popular until much more recently.","Summer camps are not a new idea; they started in the 1880s and were promoted as a cure for the alleged frailty of urban children.","Summer camps, which date back to the 1880s, were originally intended for country children, who were thought to be weaker than children in the city."],"a":2,"ex":"«Far from being X» = רחוק מלהיות X, כלומר ממש לא X. מחנות הקיץ אינם המצאה חדשה, הם התחילו בשנות ה-1880 והוצגו כתרופה לחולשה כביכול של ילדי העיר. «supposed» = כביכול, ובתשובה הנכונה «alleged». אחת השגויות אומרת שהמחנות חדשים, אחרת אומרת שבשנות ה-1880 ביקרו אותם, והרביעית מחליפה את ילדי העיר בילדי הכפר.","w":[["far from","רחוק מ..., ממש לא"],["date back to","להתחיל ב..., לחזור עד"],["supposed","כביכול, משוער"]]},{"q":"Unless the airline reduces its fuel costs significantly, it will have to cancel several of its least profitable routes next year.","o":["If the airline fails to cut its fuel costs substantially, it will be forced to drop some of its least profitable routes next year.","The airline will cancel several of its least profitable routes next year in order to reduce its fuel costs significantly.","Even if the airline reduces its fuel costs significantly, it will still have to cancel several of its least profitable routes next year.","The airline has already reduced its fuel costs significantly, so it will not have to cancel any of its routes next year."],"a":0,"ex":"«Unless» = אלא אם כן, כלומר «if not». אם חברת התעופה לא תקטין מאוד את הוצאות הדלק, היא תצטרך לבטל כמה קווים. התשובה הנכונה משתמשת ב-«if... fails to». אחת השגויות הופכת את ביטול הקווים לאמצעי לחיסכון בדלק, אחרת («even if») מבטלת את התנאי, והרביעית אומרת שהחיסכון כבר קרה, וזה לא נאמר.","w":[["unless","אלא אם כן"],["significantly","באופן משמעותי"],["profitable","רווחי"]]},{"q":"Critics of the plan point out that the new stadium, far from boosting the local economy, would mainly benefit a handful of wealthy investors.","o":["Critics of the plan admit that the new stadium would boost the local economy, but they complain that it would also benefit a few wealthy investors.","According to the plan's critics, the new stadium would do little for the local economy and would chiefly profit a small number of rich investors.","A handful of wealthy investors have criticized the plan, claiming that the new stadium would harm the local economy more than it would help it.","Critics of the plan argue that the new stadium would benefit wealthy investors only if it first managed to boost the local economy significantly."],"a":1,"ex":"לפי המבקרים, האצטדיון לא יחזק את הכלכלה המקומית («far from boosting»), אלא בעיקר ירוויחו ממנו מעט משקיעים עשירים. התשובה הנכונה אומרת את זה במילים אחרות. אחת השגויות אומרת שהמבקרים מודים שהכלכלה תתחזק, אחרת מחליפה את המבקרים במשקיעים עצמם, והרביעית מוסיפה תנאי שלא קיים במקור.","w":[["boost","לחזק, להגביר"],["benefit","להועיל, להיטיב עם"],["a handful of","קומץ, מעט"]]}]},"x2rs3":{"id":"x2rs3","tier":2,"type":"rs","qs":[{"q":"Rarely has a single invention changed daily life as dramatically as the refrigerator, which transformed not only how people store food but also how often they shop.","o":["The refrigerator changed how people store food, but it rarely affected how often they shop, so its effect on daily life was less dramatic than expected.","Many inventions have changed daily life more dramatically than the refrigerator, which mainly transformed how often people go shopping for food.","Because people began shopping less often, the refrigerator was invented to store food for longer, which dramatically changed their daily life.","Few inventions have altered everyday life as much as the refrigerator, which changed both the way people keep food and how frequently they go shopping."],"a":3,"ex":"«Rarely has X» = לעתים רחוקות X, כלומר מעט המצאות שינו את חיי היומיום כמו המקרר. המקרר שינה גם את אופן שמירת המזון וגם את תדירות הקניות («not only... but also»). התשובה הנכונה שומרת על שני החלקים. אחת השגויות טוענת שהמקרר כמעט לא השפיע על הקניות, אחרת אומרת שהמצאות רבות שינו את החיים יותר ממנו, והרביעית הופכת סיבה ותוצאה.","w":[["rarely","לעתים רחוקות"],["transform","לשנות מן היסוד"],["not only... but also","לא רק... אלא גם"]]},{"q":"The researchers stress that their findings, though promising, are based on a small sample and must be confirmed by larger studies before any treatment can be recommended.","o":["The researchers stress that, because their findings were based on a large sample, the treatment can be recommended without any further studies.","Although their findings were based on a small sample, the researchers are already recommending the treatment while larger studies are carried out.","The findings are encouraging, but the researchers emphasize that the sample was small and larger studies are needed before a treatment is recommended.","The researchers stress that their findings are disappointing and that larger studies are unlikely to change their decision not to recommend treatment."],"a":2,"ex":"המקור: הממצאים מבטיחים, אבל המדגם קטן, ולכן צריך לאשר אותם במחקרים גדולים יותר לפני שממליצים על טיפול. התשובה הנכונה אומרת זאת («encouraging» במקום «promising», «emphasize» במקום «stress»). אחת השגויות הופכת את המדגם לגדול, אחרת אומרת שהחוקרים כבר ממליצים על הטיפול, והרביעית אומרת שהממצאים מאכזבים.","w":[["stress","להדגיש"],["promising","מבטיח, מעודד"],["sample","מדגם"]]},{"q":"Whereas earlier generations of farmers in the valley grew mostly wheat, their grandchildren have turned to vineyards, which require less land but far more labor.","o":["Farmers in the valley once grew mainly wheat, but their grandchildren now cultivate grapes, which need less land and much more work.","Farmers in the valley once grew mainly grapes, but their grandchildren have switched to wheat, which needs less land and much more work.","The grandchildren of the valley's farmers grow both wheat and grapes, since vineyards need less land and less labor than wheat fields do.","Earlier generations in the valley grew mostly wheat because vineyards, which their grandchildren now prefer, required more land than they owned."],"a":0,"ex":"«Whereas» = בעוד ש..., ואילו. הדורות הקודמים גידלו בעיקר חיטה, והנכדים עברו לכרמים, שדורשים פחות אדמה אבל הרבה יותר עבודה. אחת השגויות מחליפה בין החיטה לענבים, אחרת אומרת שכרמים דורשים פחות עבודה, והרביעית ממציאה סיבה (שכרמים דרשו יותר אדמה), וזה גם סותר את המקור.","w":[["whereas","בעוד ש..., ואילו"],["vineyard","כרם"],["labor","עבודה (פיזית)"]]}]},"x2rs4":{"id":"x2rs4","tier":2,"type":"rs","qs":[{"q":"Only a small fraction of the plastic collected for recycling is actually turned into new products; the rest is burned, buried, or shipped abroad.","o":["A large proportion of the plastic collected for recycling is turned into new products, and only a small amount is burned, buried, or shipped abroad.","Most of the plastic gathered for recycling is not made into new products but is instead burned, buried, or sent to other countries.","Only a small fraction of plastic is collected for recycling, because most of it is burned, buried, or shipped abroad before it can be collected.","The plastic that is burned, buried, or shipped abroad is later turned into new products, so very little of the collected plastic is wasted."],"a":1,"ex":"«a small fraction» = חלק קטן. רק חלק קטן מהפלסטיק שנאסף למיחזור הופך למוצרים חדשים, וכל השאר נשרף, נקבר או נשלח לחו״ל. כלומר רוב הפלסטיק לא ממוחזר, וזה מה שאומרת התשובה הנכונה. אחת השגויות הופכת את הכמויות, אחרת אומרת שרק מעט פלסטיק נאסף (המקור מדבר על מה שקורה אחרי האיסוף), והרביעית סותרת את המקור.","w":[["fraction","חלק קטן, שבר"],["recycling","מיחזור"],["abroad","לחו״ל"]]},{"q":"Despite having no formal training in architecture, she designed several of the most admired public buildings of her era.","o":["Because she had no formal training in architecture, few of the public buildings that she designed were admired by people of her era.","After receiving formal training in architecture, she designed several public buildings, which were not admired until long after her era.","She admired several public buildings of her era so much that she decided to study architecture formally despite having no experience.","Although she had never formally studied architecture, she was responsible for some of the most highly regarded public buildings of her time."],"a":3,"ex":"«Despite» = למרות. למרות שלא למדה אדריכלות באופן פורמלי, היא תכננה כמה מהבניינים הציבוריים המוערכים ביותר בתקופתה. התשובה הנכונה משתמשת ב-«although» ו-«highly regarded» (מוערך). אחת השגויות הופכת את הניגוד לסיבה ואומרת שהבניינים לא הוערכו, אחרת אומרת שהיא כן למדה, והרביעית מחליפה את מי שמעריך את מי.","w":[["despite","למרות"],["formal training","הכשרה פורמלית"],["admired","מוערך, נערץ"]]},{"q":"The governor's decision to close the factory was motivated less by environmental concerns than by the fear of losing votes in the coming election.","o":["The governor closed the factory mainly out of concern for the environment, although he also feared that it might cost him votes in the election.","The governor refused to close the factory because he feared that doing so would cost him votes, despite the environmental concerns it had raised.","Worry about losing votes in the next election, rather than concern for the environment, was the main reason the governor shut the factory.","The governor's decision to close the factory, which was motivated by environmental concerns alone, caused him to lose votes in the election."],"a":2,"ex":"«less by X than by Y» = פחות בגלל X ויותר בגלל Y. הסיבה העיקרית לסגירת המפעל הייתה החשש לאבד קולות, ולא הדאגה לסביבה. התשובה הנכונה אומרת זאת עם «rather than». אחת השגויות הופכת את סדר החשיבות, אחרת אומרת שהמושל סירב לסגור את המפעל, והרביעית אומרת שהסיבה הייתה רק הסביבה ומוסיפה שהוא הפסיד קולות.","w":[["motivated by","מונע על ידי"],["concern","דאגה"],["rather than","ולא, במקום"]]}]},"x2rs5":{"id":"x2rs5","tier":2,"type":"rs","qs":[{"q":"Not only did the new software fail to speed up the processing of applications, but it also introduced errors that took months to correct.","o":["The new software did not make applications any faster to process, and it also created mistakes that needed months to fix.","The new software sped up the processing of applications, although it also introduced several errors that took months to correct.","Because it took months to correct the errors in the new software, the processing of applications did not speed up at all.","The new software introduced no errors, but it failed to speed up the processing of applications as much as had been promised."],"a":0,"ex":"«Not only... but also» = לא רק... אלא גם. התוכנה החדשה לא זירזה את הטיפול בבקשות, וגם יצרה שגיאות שלקח חודשים לתקן. התשובה הנכונה שומרת על שני הכישלונות. אחת השגויות אומרת שהתוכנה כן זירזה את הטיפול, אחרת הופכת את השגיאות לסיבה, והרביעית אומרת שלא היו שגיאות.","w":[["not only... but also","לא רק... אלא גם"],["fail to","לא להצליח ל..."],["introduce","להכניס, ליצור"]]},{"q":"Most visitors to the national park never venture more than a kilometer from the parking lots, leaving its vast interior almost untouched.","o":["Because the vast interior of the national park is almost untouched, most visitors are not allowed to go more than a kilometer from the parking lots.","Since the majority of the park's visitors stay within about a kilometer of the parking areas, its huge interior remains nearly undisturbed.","Most visitors to the national park walk several kilometers from the parking lots, so few parts of its vast interior remain untouched.","Only a few visitors to the national park stay near the parking lots, while the rest explore its vast interior, which is almost untouched."],"a":1,"ex":"«venture» = להעז ללכת, להתרחק. רוב המבקרים לא מתרחקים יותר מקילומטר מהחניונים, ולכן הפנים העצום של הפארק נשאר כמעט בלי מגע אדם. התשובה הנכונה אומרת זאת. אחת השגויות הופכת סיבה ותוצאה ומוסיפה איסור, ושתי האחרות אומרות שרוב המבקרים כן מתרחקים.","w":[["venture","להעז ללכת, להרחיק"],["vast","עצום, נרחב"],["untouched","שלא נגעו בו"]]},{"q":"The professor argued that the economic crisis was not caused by the collapse of the banks; rather, the banks collapsed because the crisis had already begun.","o":["The professor argued that the collapse of the banks caused the economic crisis, which did not begin until the banks had already failed.","The professor argued that the economic crisis and the collapse of the banks were caused by the same factors and began at the same time.","According to the professor, the banks collapsed for reasons that had nothing to do with the economic crisis, which began much later.","In the professor's view, the crisis was already under way when the banks failed, so their failure was its result rather than its cause."],"a":3,"ex":"«rather» = אלא, נהפוך הוא. לפי הפרופסור קריסת הבנקים לא גרמה למשבר, אלא היא נבעה ממשבר שכבר התחיל. התשובה הנכונה אומרת שהקריסה הייתה תוצאה ולא סיבה. אחת השגויות הופכת בדיוק את הסיבה והתוצאה, אחרת אומרת ששניהם התחילו באותו זמן, והרביעית מנתקת את הקשר בין השניים.","w":[["collapse","קריסה"],["rather","אלא, נהפוך הוא"],["under way","בעיצומו, כבר מתרחש"]]}]},"x2rs6":{"id":"x2rs6","tier":2,"type":"rs","qs":[{"q":"Although sharks are often portrayed as relentless hunters of humans, attacks on people are extremely rare, and most of them appear to be cases of mistaken identity.","o":["Because sharks often mistake people for other prey, their attacks on humans are much more common than most films and books usually suggest.","Sharks are rarely portrayed as hunters of humans, although they attack people quite often and seem to mistake them for their usual prey.","Sharks are often depicted as hunting people, yet they seldom attack humans, and most attacks seem to result from mistaking people for other prey.","Sharks attack humans only rarely, but when they do, they almost always recognize them as people and hunt them deliberately."],"a":2,"ex":"«portray» = לתאר, להציג. כרישים מוצגים כציידי בני אדם, אבל בפועל הם תוקפים אנשים לעתים נדירות מאוד, ורוב ההתקפות נובעות מטעות בזיהוי. התשובה הנכונה אומרת זאת («seldom» במקום «extremely rare»). שתי שגויות אומרות שההתקפות נפוצות, והרביעית אומרת שהכרישים מזהים את האנשים ותוקפים בכוונה, וזה ההפך מ-«mistaken identity».","w":[["portray","לתאר, להציג"],["relentless","בלתי נלאה, שאינו מרפה"],["mistaken identity","טעות בזיהוי"]]},{"q":"The museum's decision to charge an entrance fee, which was meant to raise money for repairs, has instead driven away so many visitors that its income has actually fallen.","o":["The museum began charging admission to pay for repairs, but this has scared off so many visitors that it now earns less than before.","The museum's income has fallen so much that it has been forced to charge an entrance fee in order to pay for the necessary repairs.","The entrance fee has driven away some visitors, but it has still raised enough money for the museum to carry out the planned repairs.","Many visitors stopped coming to the museum because of the repairs, so it decided to charge an entrance fee to make up for the lost income."],"a":0,"ex":"דמי הכניסה נועדו לגייס כסף לשיפוצים, אבל במקום זה («instead») הם הרחיקו כל כך הרבה מבקרים שההכנסות דווקא ירדו. התשובה הנכונה אומרת זאת («earns less than before»). אחת השגויות הופכת סיבה ותוצאה, אחרת אומרת שהכסף בכל זאת הספיק לשיפוצים, והרביעית אומרת שהשיפוצים הרחיקו את המבקרים.","w":[["charge a fee","לגבות תשלום"],["drive away","להרחיק, להבריח"],["income","הכנסה"]]},{"q":"Few of the town's residents could have predicted that the abandoned railway line, long considered an eyesore, would one day become its most popular attraction.","o":["Most of the town's residents predicted that the abandoned railway line would become popular, even though visitors considered it an eyesore.","Hardly anyone in the town expected the old disused railway, which people had long regarded as ugly, to turn into its greatest attraction.","The town's residents considered the railway line their most popular attraction until it was abandoned and became an eyesore.","Few of the town's residents visit the abandoned railway line, which tourists consider an eyesore despite its great popularity."],"a":1,"ex":"«eyesore» = דבר מכוער שפוגע בנוף. מעט תושבים יכלו לצפות שקו הרכבת הנטוש, שנחשב זמן רב למכוער, יהפוך לאטרקציה הפופולרית ביותר. התשובה הנכונה אומרת זאת («hardly anyone» במקום «few»). אחת השגויות אומרת שרוב התושבים צפו את זה, אחרת הופכת את סדר הזמנים, והרביעית אומרת שתושבים מעטים מבקרים שם.","w":[["eyesore","מפגע חזותי, דבר מכוער"],["abandoned","נטוש"],["predict","לחזות, לצפות"]]}]},"x2rc1":{"id":"x2rc1","tier":2,"type":"rc","title":"The Great Stink: A Right Decision for the Wrong Reason","text":["In the summer of 1858, London was overwhelmed by a smell. For decades the city had poured its waste directly into the Thames, and an unusually hot, dry season reduced the river's flow and left the sewage baking in the sun. Newspapers called the episode the Great Stink. Members of Parliament, whose building stood on the riverbank, soaked the curtains in chemicals in a desperate attempt to block the odor, and there was serious talk of moving the government out of the city altogether.","The smell alone might not have provoked action had it not been for a widely held theory about disease. Most doctors at the time believed that illnesses such as cholera were caused by 'miasma', a poisonous vapor rising from rotting matter. If the air above the Thames was foul, they reasoned, it must also be deadly. Within weeks, a bill that had been delayed for years was passed, giving the engineer Joseph Bazalgette the funds to build a vast network of sewers that would carry the city's waste far downstream, away from where people lived.","The miasma theory was wrong. A few years earlier, a physician named John Snow had traced an outbreak of cholera to a single contaminated water pump, concluding that the disease spread through drinking water rather than through the air. His argument persuaded few of his colleagues. Ironically, however, Bazalgette's sewers solved the very problem Snow had identified: by keeping sewage out of the river from which much of the city drew its water, they cut off the route by which cholera actually traveled. After the system was completed, the disease never again struck London on the scale of earlier epidemics.","Historians sometimes cite the Great Stink as an example of a right decision made for the wrong reasons. It also illustrates how rarely evidence by itself drives public spending. Snow's careful research had changed almost nothing; a few weeks of unpleasant air, felt directly by the people who controlled the budget, changed a great deal."],"qs":[{"q":"The main purpose of the passage is to","o":["explain why Parliament rejected John Snow's research on cholera","argue that the miasma theory was more accurate than its critics claimed","compare London's sewer system with those of other large cities","describe how a public health improvement grew out of a mistaken belief"],"a":3,"ex":"הקטע מספר איך הסירחון של 1858, יחד עם האמונה השגויה ב-miasma (אדים רעילים), הוביל לבניית מערכת הביוב, ואיך הביוב עצר בכל זאת את הכולרה. כלומר שיפור בבריאות הציבור שנולד מתוך טעות. הקטע לא אומר שהפרלמנט דחה את המחקר של סנואו (רק שהוא שכנע מעט עמיתים), וגם אומר במפורש שתאוריית ה-miasma הייתה שגויה.","w":[["mistaken","שגוי, מוטעה"],["sewer","ביוב, תעלת ביוב"],["sewage","שפכים"]]},{"q":"According to the first paragraph, the smell in the summer of 1858 was made worse by","o":["chemicals that were used to treat the curtains of Parliament","hot, dry weather that reduced the flow of the river","a sudden increase in the population of the city","the construction of new sewers along the riverbank"],"a":1,"ex":"בפסקה 1 כתוב: «an unusually hot, dry season reduced the river's flow and left the sewage baking in the sun», כלומר מזג אוויר חם ויבש הקטין את זרימת הנהר. הכימיקלים על הווילונות נועדו לחסום את הריח ולא גרמו לו, והביוב החדש נבנה רק אחרי האירוע.","w":[["flow","זרימה"],["overwhelm","להציף, להכריע"],["odor","ריח (רע)"]]},{"q":"In the third paragraph, the phrase 'cut off the route' is closest in meaning to","o":["shortened the journey","revealed the source","blocked the path","changed the direction"],"a":2,"ex":"«cut off» = לחסום, לנתק. הביוב הרחיק את השפכים מהנהר שממנו העיר שאבה מים, ובכך חסם את הדרך שבה הכולרה עברה בפועל (דרך מי השתייה). «revealed the source» (חשף את המקור) מפתה, כי סנואו גילה את מקור ההתפרצות, אבל הביטוי מתאר את מה שעשה הביוב, כלומר חסימה.","w":[["cut off","לחסום, לנתק"],["route","דרך, נתיב"],["contaminated","מזוהם"]]},{"q":"The word 'Ironically' in the third paragraph is used to point out that","o":["the sewers stopped cholera even though they were built to fight a false cause","John Snow himself helped Bazalgette to design part of the sewer system","Bazalgette secretly agreed with Snow but did not dare to say so","the sewers made the city's drinking water dirtier than it had been before"],"a":0,"ex":"האירוניה היא שהביוב נבנה כדי להיפטר מאוויר מסריח, מתוך אמונה שגויה שהוא גורם למחלות, ובכל זאת הוא פתר את הבעיה האמיתית שסנואו זיהה: זיהום מי השתייה. הקטע לא אומר שסנואו השתתף בתכנון או שבאזלג׳ט הסכים איתו בסתר, והביוב דווקא שמר על המים נקיים יותר.","w":[["ironically","באופן אירוני"],["identify","לזהות"],["epidemic","מגפה"]]},{"q":"It can be inferred from the last paragraph that the author believes","o":["Snow's research was carelessly conducted and therefore deserved to be ignored","public spending should never be based on scientific evidence alone","decision makers react more readily to problems they suffer from personally than to research","the Great Stink was a far less serious event than historians usually claim"],"a":2,"ex":"בפסקה האחרונה כתוב שהמחקר הקפדני של סנואו כמעט לא שינה דבר, ואילו כמה שבועות של אוויר מסריח, «felt directly by the people who controlled the budget», שינו הרבה. כלומר מקבלי ההחלטות הגיבו למה שהרגישו בעצמם יותר מאשר לראיות. המחבר מתאר את המחקר כ-«careful» (קפדני), ולכן הטענה שהוא נעשה ברשלנות סותרת את הקטע.","w":[["illustrate","להמחיש"],["cite","לצטט, להביא כדוגמה"],["budget","תקציב"]]}]},"x2rc2":{"id":"x2rc2","tier":2,"type":"rc","title":"Built by Me: Why Effort Raises Value","text":["Ask people how much they would pay for a simple storage box, and their answers will be fairly consistent. Ask the same question of people who have just spent twenty minutes assembling that box themselves, and the figure rises noticeably. Researchers who documented this pattern in a series of experiments named it the 'IKEA effect', after the furniture company whose customers famously put together their own shelves and tables. The finding suggests that labor does not merely produce things we value; it can also increase the value we place on them.","The effect appeared well beyond furniture. In one study, participants who folded paper animals following written instructions were willing to pay almost as much for their own clumsy creations as others would pay for models folded by experts, while people who had not made them regarded the amateur versions as nearly worthless. Crucially, the boost depended on completing the task. When participants built an object and then took it apart, or were stopped before finishing, their valuation of it fell back to ordinary levels.","Why should effort translate into affection? One explanation is that successfully building something makes people feel competent, and they transfer that pleasant feeling to the object itself. Another is that people dislike believing they have wasted their time, so they persuade themselves that the result was worth the trouble. The two explanations can easily coexist, and both may operate at once.","Businesses have long exploited this tendency, sometimes without understanding it. A frequently repeated story claims that instant cake mixes sold poorly until manufacturers required customers to add a fresh egg, giving home bakers a sense that they had genuinely cooked. Whether or not the story is true, the principle has a darker side. Managers who have devoted years to a failing project may overrate its prospects for the same reason that amateurs overrate their paper animals, continuing to invest long after an outsider would have given up."],"qs":[{"q":"Which of the following is the best title for the passage?","o":["Why We Value What We Make Ourselves","How Furniture Companies Cut Their Costs","The Art of Folding Paper Animals","Why Unfinished Projects Are Worth More"],"a":0,"ex":"הקטע כולו עוסק בתופעה שבה אנשים מעריכים יותר דברים שבנו בעצמם: הניסויים (פסקאות 1 ו-2), ההסברים (פסקה 3) והשימוש בעסקים (פסקה 4). קיפול חיות נייר הוא רק דוגמה אחת, ולפי פסקה 2 דווקא דברים שלא הושלמו לא מקבלים ערך נוסף.","w":[["value","להעריך; ערך"],["assemble","להרכיב"],["labor","עבודה, עמל"]]},{"q":"According to the second paragraph, what happened when participants were stopped before they finished building an object?","o":["They valued it more highly than the experts' models","They asked to be allowed to complete it at home","They were willing to pay extra in order to finish it","They valued it no more highly than people usually do"],"a":3,"ex":"בפסקה 2 כתוב שכאשר עצרו את המשתתפים לפני שסיימו, «their valuation of it fell back to ordinary levels», כלומר הם העריכו את החפץ כמו כל אחד אחר, בלי תוספת. «Crucially, the boost depended on completing the task» מראה שהתוספת בערך תלויה בסיום המשימה. הקטע לא מזכיר בקשה לסיים בבית או נכונות לשלם כדי לסיים.","w":[["crucially","באופן מכריע, וזה העיקר"],["valuation","הערכת שווי"],["boost","דחיפה, תוספת"]]},{"q":"In the last paragraph, the word 'exploited' is closest in meaning to","o":["failed to notice","taken advantage of","openly criticized","carefully measured"],"a":1,"ex":"«exploit» = לנצל. עסקים ניצלו את הנטייה הזאת, לפעמים בלי להבין אותה, כמו בסיפור על תערובות העוגה. «failed to notice» (לא שמו לב) מפתה בגלל «without understanding it», אבל אפשר לנצל משהו בלי להבין אותו, והדוגמה מראה שימוש פעיל בנטייה ולא התעלמות ממנה.","w":[["exploit","לנצל"],["tendency","נטייה"],["take advantage of","לנצל, להפיק תועלת מ..."]]},{"q":"The author mentions the cake mixes in the last paragraph in order to","o":["prove that food companies were the first to discover the effect","show that customers prefer products that are quick to prepare","give an example of how a business may have made use of the effect","argue that most popular stories about business are untrue"],"a":2,"ex":"הסיפור על תערובות העוגה מובא כדוגמה לכך שעסקים ניצלו את הנטייה: הוספת ביצה נתנה לאופים תחושה שהם באמת בישלו. המחבר כותב «Whether or not the story is true», ולכן הוא לא מנסה להוכיח דבר בעזרתו, וגם לא טוען שרוב הסיפורים שקריים.","w":[["genuinely","באמת, באופן אמיתי"],["manufacturer","יצרן"],["instant","מיידי, להכנה מהירה"]]},{"q":"It can be inferred from the last paragraph that managers of a failing project","o":["usually abandon it sooner than an outsider would","may judge it more favorably than someone who did not work on it","are less affected by the IKEA effect than amateurs are","rarely invest much of their own time in it"],"a":1,"ex":"כתוב שמנהלים שהשקיעו שנים בפרויקט כושל עלולים להעריך יותר מדי את סיכוייו, ולהמשיך להשקיע «long after an outsider would have given up». מכאן שהם שופטים אותו בעין יפה יותר ממי שלא עבד עליו. התשובה שהם נוטשים אותו מוקדם יותר אומרת את ההפך, והקטע משווה אותם לחובבנים, כלומר הם מושפעים מהתופעה באותה מידה.","w":[["overrate","להעריך יתר על המידה"],["prospects","סיכויים"],["give up","לוותר"]]}]},"x2rc3":{"id":"x2rc3","tier":2,"type":"rc","title":"Half Asleep: Resting One Side of the Brain","text":["For most mammals, sleep is an all-or-nothing affair: the whole brain slows down together, and the sleeper becomes largely unaware of its surroundings. Dolphins cannot afford such a luxury. Because they must rise to the surface to breathe and remain alert to predators, they have evolved the ability to rest one half of the brain while the other stays awake. During this state, the eye controlled by the waking half usually remains open, and the animal continues to swim slowly. After a while the two halves switch roles, so that each eventually gets the rest it needs.","Birds use a similar strategy, and in some cases they adjust it to their circumstances. In a well-known experiment, ducks sleeping in a row were recorded on video. Those at the ends of the row slept with the eye facing away from the group open far more often than those in the middle, and the half of the brain connected to that eye showed signs of wakefulness. In other words, the birds most exposed to danger kept watch while still getting some rest.","Even more remarkable are frigatebirds, which can stay aloft over the ocean for weeks without landing. Researchers who attached small brain monitors to these birds found that they do sleep in flight, sometimes with one hemisphere and occasionally with both. Yet they slept for less than an hour a day while flying, compared with more than twelve hours a day on land. How they cope with such a severe shortage of sleep remains unclear.","Humans were long assumed to lack any version of this ability. However, studies of people spending their first night in an unfamiliar place have found that one hemisphere sleeps less deeply than the other and responds more quickly to unusual sounds. This may explain why travelers often sleep poorly in a new hotel room: part of the brain, it seems, is still on guard. Interestingly, the imbalance largely disappears on the second night, once the surroundings have become familiar and the sleeper's brain apparently judges them to be safe."],"qs":[{"q":"Which of the following best expresses the main idea of the passage?","o":["Dolphins need more sleep than other mammals because they spend their whole lives in water.","Birds sleep more deeply when they are in groups than when they are alone.","Several animals, and perhaps humans too, can let part of the brain rest while another part stays alert.","Sleeping with one eye open is harmful to an animal's health in the long run."],"a":2,"ex":"הקטע מתאר שינה של חצי מוח אצל דולפינים (פסקה 1), ברווזים (פסקה 2) וציפורי פריגטה (פסקה 3), ומציע שגם אצל בני אדם יש גרסה של זה (פסקה 4). הקטע לא אומר שדולפינים צריכים יותר שינה, ולא טוען ששינה בעין פקוחה מזיקה.","w":[["alert","ער, דרוך"],["hemisphere","חצי (של המוח), המיספרה"],["mammal","יונק"]]},{"q":"According to the second paragraph, the ducks at the ends of the row","o":["kept open the eye facing away from the group more often","slept more deeply than the ducks in the middle of the row","kept both of their eyes closed for most of the night","woke up the other ducks whenever they sensed danger"],"a":0,"ex":"בפסקה 2 כתוב שהברווזים בקצוות ישנו «with the eye facing away from the group open far more often than those in the middle», כלומר העין שפונה החוצה הייתה פקוחה לעתים קרובות יותר. הקטע לא אומר שהם ישנו עמוק יותר (להפך, חצי מהמוח שלהם היה ער), ולא מזכיר שהם העירו את האחרים.","w":[["exposed to","חשוף ל..."],["keep watch","לשמור, לעמוד על המשמר"],["wakefulness","עירנות, מצב ער"]]},{"q":"In the third paragraph, the word 'aloft' is closest in meaning to","o":["alone","awake","underwater","in the air"],"a":3,"ex":"«aloft» = באוויר, למעלה. ציפורי הפריגטה יכולות להישאר מעל האוקיינוס שבועות «without landing» (בלי לנחות), והמשפט הבא מדבר על שינה בזמן מעוף. «awake» (ער) מפתה, אבל הפסקה אומרת שהן כן ישנות בזמן שהן באוויר.","w":[["aloft","באוויר, למעלה"],["land","לנחות; יבשה"],["cope with","להתמודד עם"]]},{"q":"Which of the following is NOT mentioned in the passage?","o":["Why dolphins need to stay partly alert","How long frigatebirds sleep on land","How an unfamiliar place affects human sleep","How many hours a day dolphins sleep"],"a":3,"ex":"הקטע מסביר למה דולפינים צריכים להישאר ערים בחלקם (כדי לעלות לנשום ולהיזהר מטורפים), מציין שציפורי פריגטה ישנות יותר משתים עשרה שעות ביום על היבשה, ומתאר שינה של בני אדם במקום חדש. כמה שעות ביום דולפינים ישנים לא נאמר בשום מקום.","w":[["unfamiliar","לא מוכר, זר"],["predator","טורף"],["evolve","להתפתח (באבולוציה)"]]},{"q":"The author suggests that a traveler's poor sleep in a new hotel room may be","o":["a way of staying alert to possible danger","caused by the unusual noises found in most hotels","a sign that both halves of the brain are fully awake","more common among people who rarely travel"],"a":0,"ex":"בפסקה האחרונה כתוב שבלילה הראשון במקום חדש חצי אחד של המוח ישן פחות עמוק ומגיב מהר לקולות חריגים, ולכן «part of the brain... is still on guard», כלומר נשאר דרוך מפני סכנה. הקטע לא אומר שבבתי מלון יש רעשים חריגים, ולא שני חצאי המוח ערים לגמרי, אלא רק חצי אחד ישן פחות עמוק.","w":[["on guard","על המשמר, דרוך"],["respond","להגיב"],["poorly","באופן גרוע"]]}]},"x3sc1":{"id":"x3sc1","tier":3,"type":"sc","qs":[{"q":"Although the senator's speech was widely praised for its eloquence, critics noted that it was conspicuously ___ on the question of how the proposed reforms would actually be paid for.","o":["explicit","emphatic","exhaustive","vague"],"a":3,"ex":"«Vague» = מעורפל, לא ברור. המילה «Although» מציגה ניגוד: הנאום זכה לשבחים, אבל המבקרים מצאו בו חיסרון בשאלת המימון. «explicit» (מפורש) ו-«exhaustive» (ממצה) הם שבחים, ולכן אין בהם ניגוד ואין סיבה שמבקרים יציינו אותם.","w":[["vague","מעורפל, לא ברור"],["conspicuously","באופן בולט"],["exhaustive","ממצה, מקיף"]]},{"q":"Attendance at the museum rose sharply last year. ___, the board is reluctant to treat the rise as a lasting trend, since much of it came from a single blockbuster exhibition.","o":["Accordingly","Likewise","Nevertheless","In addition"],"a":2,"ex":"«Nevertheless» = למרות זאת. הנתונים עלו, ובכל זאת ההנהלה לא ממהרת לראות בכך מגמה קבועה. «Accordingly» (בהתאם לכך) היה הופך את ההססנות לתוצאה של העלייה, וזה לא הגיוני. «Likewise» (באופן דומה) מציג דמיון ולא ניגוד.","w":[["nevertheless","למרות זאת"],["reluctant","מהסס, לא ששׂ"],["accordingly","בהתאם לכך, לכן"]]},{"q":"The new evidence did not merely weaken the prosecution's case; it ___ it entirely, showing that the accused had been in another country on the night of the crime.","o":["bolstered","demolished","corroborated","prolonged"],"a":1,"ex":"«Demolish» = להרוס לגמרי, לנפץ (טיעון). המבנה «did not merely weaken... it ___ it entirely» מחייב פועל חזק יותר מ-«weaken». «bolster» ו-«corroborate» (לחזק, לאשש) הם ההפך: ראיה שהנאשם היה במדינה אחרת לא מחזקת את התביעה.","w":[["demolish","להרוס, לנפץ"],["bolster","לחזק, לתמוך"],["corroborate","לאשש, לאמת"]]},{"q":"Because the manuscript had been copied by hand many times over three centuries, scholars regard any single surviving version as an ___ guide to what the author originally wrote.","o":["unreliable","infallible","authoritative","impartial"],"a":0,"ex":"«Unreliable» = לא אמין. העתקה ידנית חוזרת במשך מאות שנים מכניסה שגיאות, ולכן אי אפשר לסמוך על עותק יחיד. «infallible» (חסין טעויות) ו-«authoritative» (מוסמך, מהימן) אומרים את ההפך מהמסקנה שעולה מ-«Because».","w":[["unreliable","לא אמין"],["infallible","חסין טעויות"],["authoritative","מוסמך, בר-סמכא"]]}]},"x3sc2":{"id":"x3sc2","tier":3,"type":"sc","qs":[{"q":"The committee's report was ___ in its criticism, sparing neither the minister nor the senior officials who had ignored the early warnings.","o":["tentative","perfunctory","scathing","ambivalent"],"a":2,"ex":"«Scathing» = חריף, קוטל. הדוח לא חסך ביקורת מאף אחד, לא מהשר ולא מהבכירים. «tentative» (מהוסס) ו-«ambivalent» (דו-ערכי) מתארים ביקורת חלשה או מתלבטת, וזה סותר את «sparing neither».","w":[["scathing","חריף, קוטל"],["perfunctory","שטחי, לצאת ידי חובה"],["ambivalent","דו-ערכי, מתלבט"]]},{"q":"___ his reputation as a recluse, the novelist answered every letter he received from young writers, often at considerable length.","o":["Owing to","In keeping with","Notwithstanding","By means of"],"a":2,"ex":"«Notwithstanding» = למרות. מתבודד (recluse) לא צפוי לענות לכל מכתב, ולכן יש כאן ניגוד. «In keeping with» (בהתאם ל...) ו-«Owing to» (בגלל) היו אומרים שהמוניטין שלו הוא הסיבה לכך שענה, וזה הפוך.","w":[["notwithstanding","למרות"],["recluse","מתבודד"],["in keeping with","בהתאם ל..."]]},{"q":"The first settlers had to ___ long, rainless summers, which they managed by digging deep cisterns to store the winter rain.","o":["dispense with","contend with","comply with","tamper with"],"a":1,"ex":"«Contend with» = להתמודד עם (קושי). הקיץ היבש היה קושי, והבורות שחפרו היו דרך ההתמודדות. «dispense with» (לוותר על) לא מתאים לתנאי מזג אוויר, ו-«comply with» (לציית ל...) מתאים לחוקים ולא לקיץ.","w":[["contend with","להתמודד עם"],["dispense with","לוותר על, להסתדר בלי"],["cistern","בור מים"]]},{"q":"The software update was meant to fix a minor security flaw, but it ___ introduced a far more serious one, which went unnoticed for months.","o":["deliberately","scrupulously","ostensibly","inadvertently"],"a":3,"ex":"«Inadvertently» = בלי כוונה, בשוגג. העדכון נועד לתקן, ובטעות יצר פרצה חמורה יותר. «deliberately» (בכוונה) סותר את «meant to fix», ו-«ostensibly» (לכאורה) לא מתאר פעולה שבאמת קרתה.","w":[["inadvertently","בשוגג, בלי כוונה"],["ostensibly","לכאורה"],["scrupulously","בקפדנות"]]}]},"x3sc3":{"id":"x3sc3","tier":3,"type":"sc","qs":[{"q":"To the untrained eye the two species look almost identical, ___ their songs differ so markedly that experienced birdwatchers can tell them apart at once.","o":["so that","whereas","inasmuch as","provided that"],"a":1,"ex":"«Whereas» = בעוד ש..., ואילו. יש ניגוד בין המראה הזהה לשירה השונה. «inasmuch as» (מאחר ש...) מציג סיבה, אבל השירה השונה איננה הסיבה לכך שהמינים נראים זהים. «provided that» (בתנאי ש...) מציג תנאי ולא ניגוד.","w":[["whereas","בעוד ש..., ואילו"],["markedly","באופן ניכר"],["inasmuch as","מאחר ש..."]]},{"q":"The archive's catalogue is so ___ that researchers may spend days searching for a document that has been listed under three different names.","o":["meticulous","haphazard","concise","lucid"],"a":1,"ex":"«Haphazard» = אקראי, חסר סדר. מסמך שרשום בשלושה שמות שונים מעיד על קטלוג מבולגן. «meticulous» (קפדני) ו-«lucid» (בהיר) הם ההפך, וקטלוג כזה היה מקל על החיפוש.","w":[["haphazard","אקראי, חסר סדר"],["meticulous","קפדני, מדוקדק"],["lucid","בהיר"]]},{"q":"Rather than ___ the old factory, as many residents had feared it would, the city chose to convert it into apartments, preserving its brick walls and tall windows.","o":["raze","preserve","refurbish","commemorate"],"a":0,"ex":"«Raze» = להרוס עד היסוד. התושבים חששו מהריסה, והעירייה בחרה במקום זה להסב את המבנה ולשמר את קירותיו. «preserve» (לשמר) ו-«refurbish» (לשפץ) הם בדיוק מה שהעירייה עשתה, ולכן לא יכולים לבוא אחרי «Rather than», וגם אין סיבה לחשוש מהם.","w":[["raze","להרוס עד היסוד"],["refurbish","לשפץ, לחדש"],["convert","להסב, להמיר"]]},{"q":"The drought destroyed most of the region's wheat; ___, farmers who had planted a hardier, drought-resistant variety harvested almost as much as in a normal year.","o":["as a result","in the same way","by contrast","that is to say"],"a":2,"ex":"«By contrast» = לעומת זאת. רוב החיטה נהרסה, אבל החקלאים שזרעו זן עמיד קצרו כרגיל. «as a result» (כתוצאה מכך) היה אומר שהבצורת גרמה ליבול טוב, וזה לא הגיוני. «that is to say» (כלומר) מציג הסבר של אותו דבר, ולא ניגוד.","w":[["by contrast","לעומת זאת"],["hardy","עמיד, חסון"],["that is to say","כלומר"]]}]},"x3sc4":{"id":"x3sc4","tier":3,"type":"sc","qs":[{"q":"The professor's lectures were notoriously ___, wandering from one subject to another so freely that students struggled to take coherent notes.","o":["succinct","rigorous","monotonous","digressive"],"a":3,"ex":"«Digressive» = נוטה לסטות מהנושא. ההרצאות נדדו מנושא לנושא, וזו בדיוק ההגדרה. «succinct» (תמציתי) ו-«rigorous» (קפדני, שיטתי) הם ההפך. «monotonous» (חדגוני) מתאר טון אחיד, ולא קפיצה בין נושאים.","w":[["digressive","סוטה מהנושא"],["succinct","תמציתי"],["coherent","קוהרנטי, מסודר והגיוני"]]},{"q":"___ the treaty was signed in 1648, sporadic fighting continued along the border for nearly a decade.","o":["In case","Inasmuch as","Provided that","Even though"],"a":3,"ex":"«Even though» = למרות ש... החתימה על הסכם השלום הייתה אמורה לסיים את הלחימה, אבל היא נמשכה. «Inasmuch as» (מאחר ש...) מציג סיבה, אבל החתימה איננה הסיבה להמשך הלחימה. «Provided that» (בתנאי ש...) ו-«In case» (למקרה ש...) מציגים תנאי, ואילו כאן מדובר בעובדה היסטורית.","w":[["even though","למרות ש..."],["inasmuch as","מאחר ש..."],["sporadic","ספורדי, לא סדיר"]]},{"q":"The witness's account was ___ by the security footage, which showed exactly the sequence of events she had described.","o":["corroborated","contradicted","fabricated","embellished"],"a":0,"ex":"«Corroborate» = לאשש, לאמת. הצילומים הראו בדיוק את מה שהעדה תיארה, ולכן הם אישרו את דבריה. «contradict» (לסתור) הוא ההפך. «fabricate» (לבדות) ו-«embellish» (לייפות) הם דברים שעושה אדם, לא מצלמת אבטחה.","w":[["corroborate","לאשש, לאמת"],["fabricate","לבדות, לפברק"],["embellish","לייפות, לקשט"]]},{"q":"Having lived through two currency collapses, the old shopkeeper remained deeply ___ about keeping his savings in a bank.","o":["complacent","apprehensive","nonchalant","sanguine"],"a":1,"ex":"«Apprehensive» = חושש, מודאג. מי שחווה שתי קריסות של המטבע חושש להפקיד כסף בבנק. «sanguine» (אופטימי) ו-«nonchalant» (אדיש, שליו) הם ההפך, ו-«complacent» (שאנן) גם הוא לא מתאים למי שנכווה פעמיים.","w":[["apprehensive","חושש, מודאג"],["sanguine","אופטימי"],["complacent","שאנן"]]}]},"x3sc5":{"id":"x3sc5","tier":3,"type":"sc","qs":[{"q":"The theory accounts for the results of the first experiment remarkably well; ___, it cannot explain those of the second, which was carried out under almost identical conditions.","o":["hence","by the same token","be that as it may","in particular"],"a":2,"ex":"«Be that as it may» = יהיה אשר יהיה, למרות זאת. התאוריה מסבירה היטב את הניסוי הראשון, אבל נכשלת בשני, ולכן צריך מילת ניגוד. «hence» (לכן) ו-«by the same token» (מאותה סיבה) מציגים המשך הגיוני ולא ניגוד.","w":[["be that as it may","יהיה אשר יהיה, למרות זאת"],["by the same token","מאותה סיבה, באותו אופן"],["account for","להסביר"]]},{"q":"The disease spread rapidly through the colony, because the ants' habit of sharing food left every member highly ___ to infection.","o":["immune","susceptible","averse","impervious"],"a":1,"ex":"«Susceptible to» = חשוף ל..., פגיע ל... שיתוף המזון הפיץ את המחלה, כלומר הנמלים היו פגיעות. «immune» (חסין) ו-«impervious» (בלתי חדיר) הם ההפך. «averse to» (סולד מ...) מתאר רצון ולא פגיעות.","w":[["susceptible","פגיע, רגיש"],["impervious","בלתי חדיר, עמיד"],["averse","סולד, מתנגד"]]},{"q":"The author's prose is deceptively simple: short sentences and everyday words ___ a structure of considerable complexity.","o":["expose","clarify","preclude","conceal"],"a":3,"ex":"«Conceal» = להסתיר. «deceptively simple» = פשוט רק לכאורה, כלומר הפשטות החיצונית מסתירה מבנה מורכב. «expose» (לחשוף) ו-«clarify» (להבהיר) הם ההפך: אם המילים היו חושפות את המורכבות, הפשטות לא הייתה מטעה.","w":[["conceal","להסתיר"],["deceptively","באופן מטעה"],["prose","פרוזה"]]},{"q":"___ the funding is approved by the end of the month, the excavation will have to be suspended until next spring.","o":["Provided that","Now that","As long as","Unless"],"a":3,"ex":"«Unless» = אלא אם כן. החפירה תיעצר אם המימון לא יאושר. «Provided that» ו-«As long as» (בתנאי ש...) היו הופכים את ההיגיון: אישור המימון היה גורם להפסקה. «Now that» (עכשיו כש...) מניח שהמימון כבר אושר.","w":[["unless","אלא אם כן"],["suspend","להשעות, לעצור זמנית"],["provided that","בתנאי ש..."]]}]},"x3sc6":{"id":"x3sc6","tier":3,"type":"sc","qs":[{"q":"Far from being the ___ figure in the movement that later historians portrayed, she in fact wrote most of its key pamphlets.","o":["marginal","pivotal","controversial","charismatic"],"a":0,"ex":"«Marginal» = שולי. «Far from being» מציג ניגוד: ההיסטוריונים תיארו אותה כשולית, אבל בפועל היא כתבה את רוב החוברות. «pivotal» (מרכזי) הוא בדיוק מה שהיא הייתה, ולכן אין ניגוד. «controversial» (שנוי במחלוקת) לא עומד בניגוד לכתיבת החוברות.","w":[["marginal","שולי"],["pivotal","מרכזי, מכריע"],["far from","רחוק מ..., ההפך מ..."]]},{"q":"The policy succeeded in reducing emissions, ___ at a far higher cost than its designers had predicted.","o":["whereby","lest","albeit","hence"],"a":2,"ex":"«Albeit» = אם כי. המדיניות הצליחה, אבל בעלות גבוהה, וזו הסתייגות. «hence» (לכן) היה הופך את העלות לתוצאה של ההצלחה, ו-«lest» (פן, כדי שלא) לא מתאים לא במשמעות ולא בתחביר.","w":[["albeit","אם כי"],["whereby","שבאמצעותו"],["lest","פן, כדי שלא"]]},{"q":"The negotiations reached an ___ when neither side was willing to make the first concession.","o":["accord","overture","epiphany","impasse"],"a":3,"ex":"«Impasse» = מבוי סתום. אף צד לא היה מוכן לוותר, ולכן המשא ומתן נתקע. «accord» (הסכם) הוא ההפך. «overture» (פנייה ראשונית, הצעה) מתאר צעד שאיש לא היה מוכן לעשות.","w":[["impasse","מבוי סתום"],["concession","ויתור"],["overture","פנייה, הצעה ראשונית"]]},{"q":"The bacteria can lie ___ in the soil for years, causing no harm until conditions become warm and wet enough for them to multiply.","o":["virulent","rampant","abundant","dormant"],"a":3,"ex":"«Dormant» = רדום, לא פעיל. החיידקים לא מזיקים ולא מתרבים עד שהתנאים משתנים. «virulent» (אלים, מדבק מאוד) ו-«rampant» (משתולל, מתפשט) סותרים את «causing no harm».","w":[["dormant","רדום"],["virulent","אלים, ארסי"],["rampant","משתולל, מתפשט"]]}]},"x3rs1":{"id":"x3rs1","tier":3,"type":"rs","qs":[{"q":"Not until the archive was digitized did historians realize that many of the letters attributed to the general had in fact been drafted by his secretary.","o":["Historians had long known that the general's secretary drafted many of his letters, and digitizing the archive merely confirmed what they already believed.","Historians discovered that many letters credited to the general had really been written by his secretary only after the archive was put into digital form.","Once the archive was digitized, historians found that the general himself had drafted many of the letters previously credited to his secretary.","Historians realized that every one of the general's letters had been written by his secretary, which is why they then decided to digitize the entire archive."],"a":1,"ex":"«Not until... did historians realize» = רק אחרי ש... הבינו ההיסטוריונים. כלומר הגילוי שהמזכיר כתב רבים מהמכתבים בא רק אחרי הדיגיטציה. התשובה שבה הגנרל כתב את המכתבים של המזכיר מחליפה מי עשה מה, וזו שבה ידעו זאת מזמן הופכת את המקור.","w":[["not until","רק כאשר, לא לפני ש..."],["attribute to","לייחס ל..."],["draft","לנסח טיוטה"]]},{"q":"So scarce was fresh water on the island that visiting ships were obliged to bring their own supply, a practice that continued well after a desalination plant had been built.","o":["Because visiting ships always brought their own fresh water, the island's residents never needed to build a desalination plant, although water there was somewhat scarce.","Fresh water on the island was so limited that ships calling there had to bring their own, a practice that lasted long after a desalination plant was built.","Fresh water on the island was so limited that ships had to carry their own, until a desalination plant was built and the practice stopped at once.","Ships visiting the island were obliged to supply its residents with fresh water, a practice that ended as soon as a desalination plant had been built on the island."],"a":1,"ex":"«So scarce was... that» = כל כך מעט מים היו, עד ש... האוניות נאלצו להביא מים משלהן, והנוהג נמשך גם הרבה אחרי שנבנה מתקן ההתפלה. התשובה שבה הנוהג נפסק מיד סותרת את «continued well after», וזו שבה האוניות סיפקו מים לתושבים מחליפה מי נותן למי.","w":[["scarce","נדיר, מועט"],["be obliged to","להיות מחויב, להיאלץ"],["desalination","התפלה"]]},{"q":"While the drug does little to cure the infection itself, it markedly shortens the period during which patients can pass the virus on to others.","o":["The drug cures the infection effectively, but it does little to shorten the period during which patients can transmit the virus to others.","Because the drug shortens the period in which patients are contagious, it is also the most effective treatment for the infection itself.","Although the drug barely treats the infection, it considerably reduces the length of time in which patients are able to infect other people.","The drug does little to cure the infection, and it only slightly shortens the time during which patients can pass the virus to others."],"a":2,"ex":"«Does little to cure» = כמעט לא מרפאה, ו-«markedly shortens» = מקצרת באופן ניכר. התשובה שבה התרופה מרפאה היטב הופכת את שני החלקים, וזו עם «only slightly» משנה את המידה: במקור הקיצור ניכר ולא קל.","w":[["markedly","באופן ניכר"],["do little to","כמעט לא (עוזר ל...)"],["contagious","מדבק"]]}]},"x3rs2":{"id":"x3rs2","tier":3,"type":"rs","qs":[{"q":"Were it not for a handful of volunteers who catalogued the seeds by hand, the collection would almost certainly have been lost when the institute's funding was cut.","o":["Although a handful of volunteers catalogued the seeds by hand, almost the entire collection was lost when the institute's funding was cut.","The institute cut its funding because a handful of volunteers had already catalogued the whole seed collection by hand, so paid staff were no longer needed.","A few volunteers would have catalogued the seeds by hand if the institute's funding had not been cut, but the collection was lost anyway.","The collection survived the institute's funding cut mainly because a few volunteers catalogued its seeds by hand; without them it would very likely have vanished."],"a":3,"ex":"«Were it not for» = אילולא. כלומר המתנדבים היו, והם שהצילו את האוסף. התשובה שבה האוסף אבד בכל זאת הופכת את המקור, וזו שבה המתנדבים הם הסיבה לקיצוץ מוסיפה קשר סיבתי שלא נאמר.","w":[["were it not for","אילולא"],["a handful of","קומץ, מעט"],["catalogue","לקטלג"]]},{"q":"The critics' hostility, far from damaging the play's prospects, seems only to have increased the public's curiosity about it.","o":["The public's curiosity about the play was sharply reduced by the critics' hostility, which seriously harmed its chances of success.","Rather than hurting the play's chances, the critics' negative response appears to have made the public even more curious about it.","The critics were hostile to the play because the public was so curious about it, although this did little to harm its prospects.","The critics' hostility neither harmed the play's chances nor had any noticeable effect on how curious the public was about it."],"a":1,"ex":"«Far from damaging» = רחוק מלפגוע, כלומר לא פגע אלא להפך. העוינות של המבקרים רק הגבירה את הסקרנות. התשובה שבה העוינות פגעה בהצגה הופכת את המקור, וזו שבה לא הייתה לה השפעה סותרת את «increased».","w":[["far from","רחוק מ..., ההפך מ..."],["hostility","עוינות"],["prospects","סיכויים"]]},{"q":"Only in the last decade have economists begun to treat household chores as work with measurable value, a shift that has substantially raised estimates of national output.","o":["It is only recently that economists have started to count housework as work of measurable value, and this has considerably increased estimates of national output.","For several decades economists have treated household chores as valuable work, but doing so has had little effect on estimates of national output.","Over the last decade economists have begun to measure the value of household chores, a change that has substantially lowered their estimates of national output.","Because estimates of national output have risen substantially over the last decade, economists have begun to count household chores as real work."],"a":0,"ex":"«Only in the last decade have economists begun» = רק בעשור האחרון התחילו. השינוי הזה העלה את אומדני התוצר. התשובה עם «lowered» הופכת את הכיוון, וזו שמתחילה ב-«Because estimates... have risen» הופכת סיבה ותוצאה.","w":[["chore","מטלה (בית)"],["substantially","באופן ניכר"],["output","תפוקה, תוצר"]]}]},"x3rs3":{"id":"x3rs3","tier":3,"type":"rs","qs":[{"q":"Much as the inventor resented the comparison, his early machines owed a considerable debt to designs that a rival had patented several years before.","o":["The inventor welcomed being compared with his rival, since his early machines were based heavily on designs that he himself had patented years before.","Because the inventor resented being compared with his rival, he made sure that his early machines owed nothing to the rival's earlier patents.","However much the inventor disliked the comparison, his first machines borrowed heavily from designs that a rival had patented some years earlier.","Although the inventor disliked the comparison, a rival's later machines borrowed heavily from designs that the inventor had patented several years earlier."],"a":2,"ex":"«Much as» = עד כמה ש..., למרות ש... הממציא כעס על ההשוואה, אבל המכונות שלו באמת נשענו על פטנטים של יריב. «owed a considerable debt to» = חב חוב גדול ל..., כלומר הושפע מאוד. התשובה שבה היריב שאב מהממציא מחליפה מי עשה מה, וזו שבה המכונות לא חבו דבר הופכת את המקור.","w":[["much as","למרות ש..., עד כמה ש..."],["resent","לכעוס, להתרעם על"],["owe a debt to","להיות חייב ל..., להיות מושפע מ..."]]},{"q":"The tribunal ruled that the company could not be held liable for the spill, inasmuch as the pipeline had been damaged by an earthquake that no reasonable inspection could have anticipated.","o":["The tribunal held the company responsible for the spill, since a reasonable inspection would have shown that the pipeline could not withstand an earthquake.","Since the pipeline was damaged by an earthquake that no sensible inspection could have foreseen, the tribunal found that the company was not responsible for the spill.","The tribunal ruled that the company was not liable for the spill, even though its own inspectors had predicted that an earthquake would damage the pipeline.","Although the earthquake that damaged the pipeline could not have been foreseen, the tribunal found the company partly liable for the spill that followed."],"a":1,"ex":"«Inasmuch as» = מאחר ש... החברה לא נמצאה אחראית, כי הצינור ניזוק ברעידת אדמה שאף בדיקה סבירה לא יכלה לצפות. התשובות שבהן החברה אחראית (לגמרי או חלקית) הופכות את פסק הדין, וזו שבה הפקחים חזו את הרעידה סותרת את «no reasonable inspection could have anticipated».","w":[["liable","אחראי (משפטית)"],["inasmuch as","מאחר ש..."],["anticipate","לצפות מראש"]]},{"q":"No sooner had the bridge reopened than engineers detected new cracks in its supports, forcing the authorities to close it once again.","o":["The bridge was reopened soon after engineers repaired the new cracks in its supports, and the authorities do not expect to close it again.","Engineers detected new cracks in the bridge's supports long after it had reopened, but the authorities decided to keep it open anyway.","The authorities closed the bridge for a second time before engineers had any chance to examine the cracks in its supports.","Right after the bridge was reopened, engineers found fresh cracks in its supports, so the authorities had to shut it once more."],"a":3,"ex":"«No sooner had... than» = אך... ומיד. מיד אחרי הפתיחה מחדש התגלו סדקים, והגשר נסגר שוב. התשובה עם «long after» משנה את התזמון ומוסיפה שהגשר נשאר פתוח, וזו שבה נסגר לפני כל בדיקה מהפכת את סדר האירועים.","w":[["no sooner... than","אך... ומיד"],["detect","לגלות, לזהות"],["support","תומך, עמוד תמך"]]}]},"x3rs4":{"id":"x3rs4","tier":3,"type":"rs","qs":[{"q":"That a species so dependent on a single plant has survived for millions of years suggests that the plant itself was once far more widespread than it is today.","o":["The fact that a species relying so heavily on one plant has lasted for millions of years indicates that the plant used to be much more common.","Because the plant was once far more widespread than it is today, the species that depends on it is likely to survive for millions of years more.","The species has survived for millions of years because it learned to depend on many different plants rather than on a single one.","A species dependent on a single plant could only have survived for millions of years if the plant had always been as rare as it is today."],"a":0,"ex":"«That a species... has survived... suggests» = העובדה שמין שורד... מרמזת ש... ההישרדות הארוכה היא הראיה, והמסקנה היא שהצמח היה נפוץ יותר בעבר. התשובה שמנבאת הישרדות עתידית הופכת ראיה ומסקנה, וזו שבה הצמח היה תמיד נדיר סותרת את המקור.","w":[["dependent on","תלוי ב..."],["widespread","נפוץ, רווח"],["suggest","לרמז, להצביע על"]]},{"q":"Though by no means the first to describe the phenomenon, she was the first to measure it with enough precision to make predictions possible.","o":["She was the first both to describe the phenomenon and to measure it, although her measurements were not precise enough to allow any predictions.","Others had described the phenomenon before her, but she was the first to measure it accurately enough for predictions to be made.","Although she measured the phenomenon less precisely than others had, she was the first to use her measurements to make predictions.","She was by no means the first to measure the phenomenon precisely, but she was the first to describe it in a way that made predictions possible."],"a":1,"ex":"«By no means the first to describe» = בשום אופן לא הראשונה לתאר, כלומר אחרים תיארו לפניה. החידוש שלה היה מדידה מדויקת שאפשרה תחזיות. התשובה האחרונה מחליפה בין התיאור למדידה, ו-«She was the first both to describe» סותרת את «by no means the first».","w":[["by no means","בשום אופן לא"],["precision","דיוק"],["phenomenon","תופעה"]]},{"q":"The longer a dispute goes unresolved, the more entrenched each side's position becomes, which is why mediators prefer to intervene at the earliest possible stage.","o":["Mediators prefer to wait before stepping in, since the parties to a dispute become more willing to compromise the longer it goes on.","Because mediators usually intervene only at a late stage, the positions of both sides in a dispute tend to become entrenched over time.","The longer mediators take to intervene, the more likely each side is to give up its position and settle the dispute on its own.","Mediators like to step in as early as they can, because the parties to a dispute grow increasingly inflexible the longer it remains unsettled."],"a":3,"ex":"«The longer... the more entrenched» = ככל שהסכסוך נמשך, כך העמדות מתקבעות. לכן המתווכים מעדיפים להתערב מוקדם. «entrenched» = מקובע, מושרש. התשובה שבה המתווכים מעדיפים לחכות הופכת את הקשר, וזו שבה התערבות מאוחרת גורמת להתקבעות הופכת סיבה ותוצאה.","w":[["entrenched","מקובע, מושרש"],["mediator","מתווך, מגשר"],["intervene","להתערב"]]}]},"x3rs5":{"id":"x3rs5","tier":3,"type":"rs","qs":[{"q":"Contrary to what its name implies, the city's 'Great Plague' killed fewer residents than the outbreaks of cholera that struck repeatedly in the following century.","o":["As its name suggests, the city's 'Great Plague' killed more residents than all the cholera outbreaks of the following century put together.","The city's 'Great Plague' got its name because it killed fewer residents than the cholera outbreaks that struck repeatedly in the previous century.","Despite its name, the city's 'Great Plague' caused fewer deaths among residents than the repeated cholera outbreaks of the next century.","The repeated cholera outbreaks of the following century killed fewer residents than the city's 'Great Plague', which is how the plague got its name."],"a":2,"ex":"«Contrary to what its name implies» = בניגוד למה שהשם מרמז. ה«מגפה הגדולה» הרגה פחות תושבים מהכולרה במאה שאחריה. התשובה האחרונה הופכת את ההשוואה, וזו שמסבירה את השם בכך שהרגה פחות מוסיפה קשר שלא נאמר ומשנה את המאה.","w":[["contrary to","בניגוד ל..."],["imply","לרמז"],["outbreak","התפרצות (מחלה)"]]},{"q":"Rarely do the people who stand to gain most from a reform campaign for it; more often, its loudest supporters are those who would gain nothing from it directly.","o":["Those likely to benefit most from a reform seldom campaign for it; it is usually backed most loudly by people who would receive no direct benefit.","Those who would benefit most from a reform usually campaign for it most loudly, while people who would gain nothing directly seldom support it.","People who campaign loudly for a reform rarely gain anything from it, because its benefits usually go to those who opposed it most strongly.","Reforms rarely benefit anyone directly, which is why the people who campaign for them most loudly are usually acting out of principle alone."],"a":0,"ex":"«Rarely do... campaign» = לעיתים רחוקות הם פועלים למענה. «stand to gain» = עשוי להרוויח. מי שירוויח הכי הרבה כמעט לא נאבק, והתומכים הקולניים הם מי שלא ירוויחו ישירות. התשובה הראשונה הופכת את המקור, וזו שבה הרפורמה לא מועילה לאיש מוסיפה טענה שלא נאמרה.","w":[["stand to gain","עשוי להרוויח"],["campaign for","לפעול, לנהל מאבק למען"],["rarely","לעיתים רחוקות"]]},{"q":"Valuable as the survey's findings are, they rest on responses from a group of volunteers who may have been unusually interested in the subject.","o":["The survey's findings are valuable, but they are based on answers from volunteers who may have cared about the subject more than most people.","Because the survey relied on volunteers who were especially interested in the subject, its findings have turned out to be of no value at all.","The survey's findings are valuable precisely because the volunteers who responded had been chosen for their unusual interest in the subject.","The survey's findings would be valuable if they were based on responses from volunteers rather than from people who had no interest in the subject."],"a":0,"ex":"«Valuable as... are» = יקרי ערך ככל שיהיו, כלומר הם בעלי ערך, אבל יש הסתייגות. הממצאים נשענים על מתנדבים שאולי התעניינו בנושא יותר מהרגיל. התשובה עם «of no value at all» מגזימה, וזו עם «precisely because» הופכת את ההסתייגות לסיבה לערך. גם «may have been» הופך שם לוודאות.","w":[["valuable as... are","יקרי ערך ככל שיהיו"],["rest on","להתבסס על"],["unusually","באופן חריג"]]}]},"x3rs6":{"id":"x3rs6","tier":3,"type":"rs","qs":[{"q":"Had the colony's governor not insisted on building the harbor wall, a project his council had dismissed as needlessly expensive, the storm of 1782 would have destroyed the town.","o":["The governor dismissed the harbor wall as a needlessly expensive project, and as a result the town was destroyed by the storm of 1782.","Thanks to the harbor wall, which the governor built despite his council's view that it was a waste of money, the town survived the 1782 storm.","The council insisted on building the harbor wall against the governor's wishes, and it was this wall that saved the town from the storm of 1782.","Although the governor built the harbor wall that his council had opposed, the storm of 1782 destroyed the town anyway."],"a":1,"ex":"«Had the governor not insisted» = אילו המושל לא היה מתעקש. כלומר הוא התעקש, החומה נבנתה, והעיר ניצלה. התשובה שבה המועצה התעקשה נגד המושל מחליפה מי עשה מה, ואלה שבהן העיר נהרסה סותרות את משפט התנאי.","w":[["insist on","להתעקש על"],["dismiss as","לבטל, לפטור כ..."],["needlessly","שלא לצורך"]]},{"q":"Given how little is known about the upper canopy of tropical forests, any claim that an insect found only there has become extinct should be treated with considerable caution.","o":["Since so little is understood about the tops of tropical forests, reports that an insect living only there has died out ought to be viewed very cautiously.","Because the upper canopy of tropical forests has now been studied very thoroughly, claims that insects living there have become extinct can generally be trusted.","Many insects found only in the upper canopy of tropical forests have become extinct because scientists know so little about how to protect them.","Little is known about the upper canopy of tropical forests, so claims that new insect species have been discovered there should be treated cautiously."],"a":0,"ex":"«Given how little is known» = בהתחשב בכך שיודעים כל כך מעט. לכן צריך לחשוד בטענה שחרק נכחד, אולי הוא פשוט לא נמצא. התשובה שבה הצמרת נחקרה היטב הופכת את המקור, וזו על מינים חדשים שהתגלו משנה את סוג הטענה.","w":[["given","בהתחשב ב..."],["canopy","חופה, צמרת היער"],["caution","זהירות"]]},{"q":"It was not the cost of the vaccine but the difficulty of keeping it cold during transport that limited its use in remote areas.","o":["The vaccine was used less in remote areas mainly because it was expensive, although keeping it cold during transport was also difficult.","What restricted the vaccine's use in remote regions was the problem of keeping it refrigerated on the way there, not its price.","The high cost of the vaccine and the difficulty of keeping it cold during transport were equally responsible for its limited use in remote areas.","Because the vaccine was cheap and easy to keep cold, it was used widely in remote areas despite the difficulty of transporting it there."],"a":1,"ex":"«It was not X but Y that» = לא X אלא Y. מה שהגביל את השימוש היה הקושי לשמור על קירור בהובלה, ולא המחיר. התשובה שבה המחיר הוא הסיבה העיקרית הופכת את המקור, וזו שבה שני הגורמים אחראים במידה שווה סותרת את «not the cost».","w":[["remote","מרוחק, נידח"],["limit","להגביל"],["transport","הובלה"]]}]},"x3rc1":{"id":"x3rc1","tier":3,"type":"rc","title":"When Noon Came Twice","text":["Until well into the nineteenth century, every town kept its own time. Noon was simply the moment when the sun stood highest over the local church tower, and because the sun reaches that point later the farther west one travels, clocks in Bristol ran roughly ten minutes behind those in London. The discrepancy troubled almost no one. When a journey between the two cities took the better part of a day, a few minutes either way were of no practical consequence.","The railways put an end to this indifference. A passenger crossing the country now passed through a bewildering succession of local times, and timetables had to list arrivals and departures in several of them at once. On lines where trains ran in both directions on a single track, confusion over the hour was not merely inconvenient but potentially lethal. In 1840 the Great Western Railway began running all its services on London time, and other companies soon followed; by the mid-1850s most public clocks in Britain had been adjusted to match, although the law did not formally recognize the change until 1880.","In the United States, where distances were far greater, the problem was correspondingly worse: at one point the railroads were operating on more than fifty different times. It was the companies themselves, not Congress, that finally imposed order. On 18 November 1883, a date newspapers dubbed 'the day of two noons', clocks across the country were reset to four standard zones. Some city councils and clergymen protested that the railroads had no right to dictate the hour, and a few towns clung to local time for years; federal law did not endorse the system until 1918.","An international framework took longer still. In 1884 delegates meeting in Washington chose the meridian passing through Greenwich as the starting point for the world's longitude. France, which had argued for a neutral line, abstained, and for more than a quarter of a century went on keeping Paris time. When it finally adopted the Greenwich standard in 1911, the law tactfully described the new official time as Paris time 'delayed by nine minutes and twenty-one seconds'.","What the period established, in the end, was that time had become a matter of agreement rather than astronomy. Today's zone boundaries follow political borders far more closely than they follow the sun. China, which spans nearly five geographical zones, observes a single official hour, so that in its far west the winter sun may not rise until well after nine in the morning."],"qs":[{"q":"Which of the following is the best title for the passage?","o":["The Day of Two Noons in American History","From Sun to Schedule: How Clocks Came to Be Standardized","Why France Rejected the Greenwich Meridian","The Dangers of Running Trains on a Single Track"],"a":1,"ex":"הקטע עוקב אחרי המעבר מזמן מקומי לפי השמש לזמן אחיד ומוסכם: בבריטניה, בארצות הברית, ברמה הבינלאומית, ועד המסקנה שהזמן הפך לעניין של הסכמה. «The Day of Two Noons» ו-«Why France Rejected...» הם פרטים מפסקה אחת בלבד, והסכנה במסילה יחידה היא רק דוגמה בפסקה 2.","w":[["standardize","לתקנן, להאחיד"],["discrepancy","פער, אי-התאמה"]]},{"q":"According to the third paragraph, the four time zones in the United States were","o":["introduced by the railroad companies decades before federal law endorsed them","imposed by Congress in response to protests from city councils and clergymen","accepted by every American town immediately after 18 November 1883","copied directly from the system adopted by the Great Western Railway"],"a":0,"ex":"בפסקה 3 כתוב שהחברות עצמן, «not Congress», הן שהטילו את הסדר ב-1883, והחוק הפדרלי אישר זאת רק ב-1918. מועצות ערים ואנשי דת דווקא מחו נגד השיטה, וכמה עיירות נאחזו בזמן המקומי במשך שנים, ולכן לא כל העיירות קיבלו אותה מיד.","w":[["impose","לכפות, להטיל"],["endorse","לאשר, לתמוך"],["cling to","להיאחז ב..."]]},{"q":"In the second paragraph, the word 'bewildering' is closest in meaning to","o":["confusing","dangerous","tedious","gradual"],"a":0,"ex":"«Bewildering» = מבלבל, מביך. הנוסע עבר ברצף של זמנים מקומיים, ולוחות הזמנים נאלצו להציג כמה מהם בבת אחת, וזה מבלבל. «dangerous» מפתה כי המשפט הבא מדבר על סכנה, אבל המילה עצמה מתארת בלבול ולא סכנה.","w":[["bewildering","מבלבל"],["succession","רצף, שורה"],["lethal","קטלני"]]},{"q":"The author quotes the wording of the French law of 1911 (paragraph 4) most probably in order to","o":["explain why the delegates chose Greenwich rather than a neutral line","suggest that Paris time had been calculated incorrectly for many years","prove that France had in fact adopted Greenwich time as early as 1884","show how France accepted the Greenwich standard without openly saying so"],"a":3,"ex":"החוק הגדיר את הזמן החדש כ«זמן פריז באיחור של 9 דקות ו-21 שניות», שזה בדיוק זמן גריניץ', בלי להזכיר את גריניץ'. המילה «tactfully» (בטקט) מרמזת שצרפת שמרה על כבודה. הקטע לא אומר שזמן פריז חושב לא נכון, וצרפת אימצה את התקן רק ב-1911, לא ב-1884.","w":[["tactfully","בטקט, בעדינות"],["abstain","להימנע (בהצבעה)"],["adopt","לאמץ"]]},{"q":"It can be inferred from the last paragraph that","o":["China has more official time zones than any other country in the world","the boundaries of time zones are now decided mainly by astronomers","official clock time in some places differs considerably from the time shown by the sun","most countries have abandoned the Greenwich standard in favor of local time"],"a":2,"ex":"בסין יש שעה רשמית אחת, ולכן במערב המדינה השמש זורחת בחורף רק אחרי תשע בבוקר. כלומר השעון הרשמי רחוק מאוד מזמן השמש. הפסקה אומרת שהגבולות נקבעים לפי גבולות פוליטיים ולא לפי אסטרונומיה, וסין מוצגת כמדינה עם אזור זמן אחד בלבד.","w":[["infer","להסיק"],["span","להשתרע על פני"],["observe","לקיים, לנהוג לפי (גם: לצפות)"]]}]},"x3rc2":{"id":"x3rc2","tier":3,"type":"rc","title":"The Price of Owning","text":["In a now-famous experiment, economists handed coffee mugs to half the students in a classroom and invited the others to buy them. Standard economic theory predicted that roughly half of the mugs would change hands: since the mugs had been distributed at random, there was no reason to expect those who happened to receive one to value it more highly than those who did not. In fact, few trades took place. Owners typically demanded about twice as much to part with a mug as non-owners were willing to pay for an identical one. The mere fact of possession, it seemed, had raised the object's worth in their eyes.","This pattern, which became known as the endowment effect, is most often explained by loss aversion: the tendency to feel a loss more keenly than a gain of the same size. Selling a mug is experienced as giving something up, whereas declining to buy one is merely a gain forgone, and the two are not weighed equally. On this account, the effect is not a quirk of mugs or classrooms but a basic feature of how people evaluate change.","Later research, however, has complicated the picture. The effect largely disappears among experienced dealers, who handle goods that they acquire specifically in order to resell. It is also absent for money itself; nobody demands more than ten dollars to give up a ten-dollar bill. Some economists have gone further, arguing that much of the gap in laboratory studies arises from the way the experiments are conducted: when participants are given detailed instructions and practice rounds, the difference between owners and buyers shrinks markedly, suggesting that part of it stemmed from confusion rather than attachment.","Whatever its exact scope, businesses have long acted as if the effect were real. Free trial periods, generous return policies and test drives all rely on the expectation that once a product is in a customer's hands, giving it back will feel like a loss. The effect may also help to explain why sellers of houses so often set asking prices that the market will not support.","The current debate, then, concerns less whether the endowment effect exists than how far it extends. Yet even its most cautious formulation poses a challenge to traditional theory, which assumes that a person's preferences are stable and independent of circumstance. If owning something can change how much we want it, then what we value depends, at least in part, on what we already happen to have."],"qs":[{"q":"The passage mainly discusses","o":["a tendency to overvalue what one owns, its likely cause and the limits of its reach","an experiment proving that economic theory cannot predict any market behavior","the methods that businesses use to persuade customers to return products","why experienced dealers are better than students at judging the value of goods"],"a":0,"ex":"הקטע מציג את אפקט הבעלות (פסקה 1), את ההסבר שלו (פסקה 2), את המגבלות שלו (פסקה 3) ואת המשמעות שלו. הניסוי לא «מוכיח» שהתאוריה לא חוזה שום דבר, ועסקים בכלל רוצים שלקוחות לא יחזירו מוצרים. הסוחרים המנוסים הם רק דוגמה אחת למגבלה.","w":[["overvalue","להעריך יתר על המידה"],["reach","היקף, טווח"]]},{"q":"According to the first paragraph, standard economic theory predicted that","o":["about half of the mugs would be sold by their owners","owners would ask roughly twice the price that buyers offered","few mugs would change hands because owners valued them highly","students who received mugs would value them more than other students"],"a":0,"ex":"בפסקה 1 כתוב «predicted that roughly half of the mugs would change hands», כי הספלים חולקו באקראי. שלוש האפשרויות האחרות מתארות את מה שקרה בפועל, וזה בדיוק ההפך ממה שהתאוריה צפתה.","w":[["predict","לחזות"],["at random","באקראי"],["part with","להיפרד מ..."]]},{"q":"In the second paragraph, the phrase 'a gain forgone' refers to","o":["a profit that is made by selling an object","a loss that is felt more strongly than a gain","a gain that is later lost again","a benefit that a person chooses not to take"],"a":3,"ex":"«Forgo» = לוותר על. מי שלא קונה ספל רק מוותר על רווח, ולכן «a gain forgone» הוא תועלת שאדם בוחר לא לקבל. «a loss that is felt more strongly» מפתה כי זה מופיע באותה פסקה, אבל זה מתאר את המכירה (loss) ולא את אי-הקנייה.","w":[["forgo","לוותר על"],["loss aversion","שנאת הפסד"],["keenly","בעוצמה, בחריפות"]]},{"q":"Which of the following is NOT mentioned in the passage as a case in which the endowment effect is weak or absent?","o":["goods handled by experienced dealers","exchanges involving money","goods that the owner has held for many years","experiments with detailed instructions and practice"],"a":2,"ex":"פסקה 3 מזכירה סוחרים מנוסים, כסף, וניסויים עם הוראות מפורטות וסבבי תרגול. הקטע לא אומר דבר על חפצים שבעליהם מחזיק בהם שנים רבות, ולכן זו התשובה.","w":[["absent","חסר, לא קיים"],["dealer","סוחר"],["acquire","לרכוש"]]},{"q":"It can be inferred from the last paragraph that the author believes","o":["even a limited version of the effect undermines the idea that preferences are fixed","the debate about the effect will soon be settled in favor of traditional theory","people's preferences depend entirely on the things they already own","the effect has now been shown to apply equally in all circumstances"],"a":0,"ex":"«Even its most cautious formulation poses a challenge» = גם הניסוח הזהיר ביותר מאתגר את ההנחה שההעדפות יציבות. האפשרות עם «entirely» מגזימה, כי בקטע כתוב «at least in part». האחרונה סותרת את פסקה 3, שבה האפקט נעלם במצבים מסוימים.","w":[["formulation","ניסוח"],["undermine","לערער"],["circumstance","נסיבות"]]}]},"x3rc3":{"id":"x3rc3","tier":3,"type":"rc","title":"Beneath the Forest Floor","text":["Over the past two decades, a striking image of the forest has taken hold in the public imagination. Beneath the ground, according to popular books and documentaries, trees are linked by vast fungal networks through which they share food, send warnings of insect attack and, in the case of large 'mother trees', nourish their own offspring. The forest that emerges from these accounts is less a collection of competing individuals than a cooperative community, and the idea has proved enormously appealing.","Its scientific basis is real enough, up to a point. The roots of most trees are colonized by mycorrhizal fungi, which supply them with water and soil nutrients in exchange for sugars the trees produce through photosynthesis. That much is not in dispute. Several field studies went further, reporting that carbon labeled in one tree later turned up in a neighbor, apparently carried there by fungal threads connecting the two.","In 2023, however, a group of researchers reviewed the evidence behind the most popular claims and found it considerably thinner than its reputation. Only a handful of studies had actually shown that a single fungal network joined different trees in a natural forest. In the transfer experiments, carbon could often have traveled by other routes, through the soil or through roots that had grown together. And when the reviewers tallied studies of whether connection to a network helped seedlings grow, positive, negative and neutral results turned up in roughly equal numbers. Later papers, they noted, had cited the early findings with steadily growing confidence, at times crediting them with conclusions their authors had never drawn.","The reviewers were careful not to claim that underground networks do not exist or are unimportant. Their objection was that bold assertions, particularly the notion that trees deliberately favor their own kin, had outrun the data. They also observed that the fungi are organisms in their own right, with interests of their own; a network that moves resources between trees may serve the fungus at least as much as it serves the forest.","The episode shows how readily a vivid metaphor can travel beyond the evidence that gave rise to it. The stakes are not merely academic, since some forestry guidelines now recommend preserving large old trees partly on the grounds that they sustain younger ones through such networks. There may well be other good reasons for that policy, but those who adopt it should be clear about which of their reasons rest on firm ground."],"qs":[{"q":"The main purpose of the passage is to","o":["prove that trees are not in fact connected by underground fungal networks","describe in detail how fungi exchange soil nutrients for sugars","argue that a popular view of forests goes further than the evidence supports","persuade foresters to stop preserving large old trees"],"a":2,"ex":"הכותב מציג את התמונה הפופולרית, מראה שהבסיס המדעי שלה דל מהמוניטין שלה, ומסיק שמטפורה חיה יכולה להתרחק מהראיות. בפסקה 4 כתוב במפורש שהחוקרים לא טענו שהרשתות לא קיימות, ובפסקה 5 הכותב לא מתנגד לשימור עצים זקנים.","w":[["evidence","ראיות"],["support","לתמוך, לבסס"]]},{"q":"According to the third paragraph, studies of whether connection to a network helps seedlings grow","o":["produced positive, negative and neutral results in about equal numbers","mostly showed that connected seedlings grew faster than others","were too few in number for the reviewers to count","proved that carbon reaches seedlings through roots that have grown together"],"a":0,"ex":"בפסקה 3 כתוב שכאשר החוקרים ספרו את המחקרים, תוצאות חיוביות, שליליות וניטרליות הופיעו «in roughly equal numbers». השורשים שהתאחו מוזכרים רק כדרך אפשרית אחרת להעברת פחמן בניסויי ההעברה, לא כמשהו שהוכח לגבי שתילים.","w":[["seedling","שתיל"],["tally","לספור, לסכם"],["neutral","ניטרלי"]]},{"q":"In the fourth paragraph, the phrase 'had outrun the data' means that the assertions","o":["were made before any data had been collected","were later confirmed by newer data","went further than the evidence could justify","had been abandoned in light of the data"],"a":2,"ex":"«Outrun» = לעקוף בריצה, להקדים. טענות ש«עקפו את הנתונים» הן טענות שהרחיקו לכת יותר ממה שהראיות מצדיקות. «made before any data had been collected» מפתה בגלל המשמעות של מירוץ, אבל בקטע יש נתונים, והבעיה היא שהטענות חורגות מהם.","w":[["outrun","לעקוף, להרחיק לכת מעבר ל..."],["assertion","טענה, הצהרה"],["kin","קרובי משפחה"]]},{"q":"The sentence 'That much is not in dispute' (paragraph 2) serves to","o":["show that the 2023 reviewers accepted all the earlier field studies","introduce the main criticism that the reviewers made in 2023","separate a well-established fact from claims that are more questionable","suggest that the exchange between fungi and trees benefits only the trees"],"a":2,"ex":"המשפט מסמן גבול: הקשר בין הפטריות לשורשים מבוסס, ומה שבא אחריו («went further») כבר שנוי במחלוקת. החוקרים לא קיבלו את כל המחקרים הקודמים, ובפסקה 4 דווקא נאמר שהרשת עשויה לשרת את הפטרייה לא פחות מהעצים.","w":[["dispute","מחלוקת"],["well-established","מבוסס היטב"],["questionable","מפוקפק, מוטל בספק"]]},{"q":"It can be inferred from the last paragraph that the author","o":["believes that forestry guidelines should be based on fungal research alone","regards the debate about fungal networks as being of purely academic interest","thinks that old trees should be cut down to help younger trees grow","does not necessarily oppose preserving old trees but wants the reasons for it to be sound"],"a":3,"ex":"הכותב אומר שייתכן שיש סיבות טובות אחרות למדיניות («There may well be other good reasons»), אבל מי שמאמץ אותה צריך לדעת אילו נימוקים מבוססים. «purely academic» סותר את «The stakes are not merely academic», והקטע לא ממליץ לכרות עצים זקנים.","w":[["sound","מבוסס, תקין (נימוק)"],["stakes","מה שעומד על הכף"],["sustain","לקיים, לתמוך"]]}]}};
